INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8906455a9f31565a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Nobel Prize for Peace is given in the city of _____?', '{"A":"Stockholm","B":"Oslo","C":"Brussels","D":"Copenhagen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nobel Peace Prize is awarded in Oslo, Norway.The other Nobel Prizes are awarded in Stockholm, Sweden.The Peace Prize is awarded annually on 10 December.Established: According to the will of Alfred Nobel.Last verified on 28-09-2026', 0, 0, 0, 1790965656855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_eb1186f029f64756', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Mother Teresa became famous because of his?', '{"A":"Selfishness","B":"Confidence","C":"Social welfare","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mother Teresa became famous for her social welfare and charity work.For about 45 years, she worked with the poor, sick, orphaned, and dying.She founded the Missionaries of Charity in Kolkata, India.Additional information:Born: SkopjeDied: 5 September 1997, Kolkata, IndiaAge at death: 87 yearsBurial place: Mother House of the Missionaries of Charity, KolkataLast verified on 27-09-2026', 0, 0, 0, 1790965656855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4bf9bcff79aba3fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Where is famous statute Christ the Redeemer?', '{"A":"Brazil","B":"USA","C":"UK","D":"UAE"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Christ the Redeemer is a famous statue in Rio de Janeiro, Brazil.It stands on Mount Corcovado.The statue was completed in 1931.It depicts Jesus Christ with outstretched arms.Height: About 30 meters (excluding the pedestal)It is one of the New Seven Wonders of the World.Last verified on 27-09-2026', 0, 0, 0, 1790965656855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e8e09e9160c1937e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the Currency of Myanmar (Burma)?', '{"A":"Kyat","B":"West African CFA Franc","C":"Yemeni Rial","D":"Euro"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Currency: Kyat (MMK).Myanmar, formerly called Burma.It is a country in Southeast Asia.Its capital is Naypyidaw.The old capital was Rangoon (Yangon).The official language is Burmese.The major religion is Buddhism.Founder: Aung SanParliament: Assembly of the Union (Pyidaungsu Hluttaw).Last verified on 27-09-2026', 0, 0, 0, 1790965656855) ON CONFLICT(id) DO NOTHING;
