INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8fab2b03254b4529', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When was Kamala Harris and Joe Biden assume office?', '{"A":"20 January 2021","B":"01 January 2021","C":"01 February 2021","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Joe Biden became the 46th President of the United States on 20 January 2021.Kamala Harris was sworn in as the 49th Vice President on the same day.Biden succeeded Donald Trump as President.Kamala Harris became the first woman, first Black American, and first South Asian American to serve as U.S. Vice President.Last verified on 01-09-2026', 0, 0, 0, 1790965658210) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ebbaff4669188fe7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the main reason behind the Israel–Hamas conflict?', '{"A":"Territorial and political conflict over Palestinian land and governance","B":"Territorial and economic conflict over Palestinian land and resources","C":"Political and religious conflict over Palestinian land and governance","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Main issue: Territorial and political conflictKey areas: Gaza Strip, West Bank, East JerusalemBeginning of the broader conflict: 1948 Arab–Israeli WarPalestinian territories: Gaza Strip and West BankMajor peace agreement: Oslo Accords (1993)Verified & Updated', 0, 0, 0, 1790965658210) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e097a81a70a8013d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Mohamed ElBaradei of Egypt of received Nobel Prize in _____?', '{"A":"2007","B":"2000","C":"2003","D":"2005"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohamed ElBaradei of Egypt received the Nobel Peace Prize in 2005.Along with the International Atomic Energy Agency (IAEA)"for their efforts to prevent nuclear energy from being used for military purposes and to ensure that nuclear energy for peaceful purposes is used in the safest possible way"Additional informationHe was an Egyptian diplomat and scholar.He served as the Director General of the IAEA from 1997 to 2009.Born: 17 June 1942 Cairo, EgyptParty: Constitution PartyLast updated question by NA on 07 May 2026', 0, 0, 0, 1790965658210) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c078bef7c7a78c32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When did the Euro currency come into existence?', '{"A":"1 January 1999","B":"1 January 2000","C":"1 January 2001","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Euro CurrencyLaunch Date (Electronic/Accounting): 1 January 1999Coins & Banknotes Introduced: 1 January 2002Reserve Currency Rank: 2nd largest in the worldTrade Rank: 2nd most traded currency globallyNumber of EU Member States Using Euro: 20Countries Using Euro (20):AustriaBelgiumCyprusEstoniaFinlandFranceGermanyGreeceIrelandItalyLatviaLithuaniaLuxembourgMaltaNetherlandsPortugalSlovakiaSloveniaSpainCroatiaLast verified on 18-01-2026', 0, 0, 0, 1790965658210) ON CONFLICT(id) DO NOTHING;
