INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ff950c11c352887e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which city is known as the Silicon Valley of India?', '{"A":"Mumbai","B":"Bengaluru (Bangalore)","C":"Chennai","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bengaluru (Bangalore) is known as the Silicon Valley of India.State: KarnatakaMajor industries: IT, Software, Biotechnology, AerospaceFamous companies: Infosys, Wipro, TCS, IBM, MicrosoftLast verified on 09-08-2026', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ac48ff0eebf77486', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'A narrow piece of land separating two water bodies and connected land masses is called _____?', '{"A":"Isthmus","B":"Bay","C":"Strait","D":"Weirs"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An isthmus is a narrow strip of land that connects two larger landmasses and separates two bodies of water.The Isthmus of Panama connects North America and South America.It separates the Atlantic and Pacific Oceans.The Isthmus of Suez connects Africa and Asia.It separates the Mediterranean Sea and Red Sea.Additional information:Strait: Narrow water passage connecting two larger water bodies.Bay: A water body partly surrounded by land.Last verified on 09-08-2026', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d06220c34a10765f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Pulitzer prize is awarded for outstanding work in the field of _____?', '{"A":"Scuba","B":"Science & Tech","C":"Journalism","D":"Film Industry"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pulitzer Prize is awarded for outstanding work in journalism and several other fields.It was established by Joseph Pulitzer.He was a Hungarian-American newspaper publisher.The first Pulitzer Prizes were awarded in 1917.Major categories include Journalism, Letters, Drama, and Music.The Pulitzer Prizes are administered by Columbia University in New York City.Last verified 08-08-2026', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
