INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_491748880d1948ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '1st May is observed internationally as?', '{"A":"Press Freedom Day","B":"Environment Day","C":"Earth Day","D":"Labour Day"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of Labour Day: 1 May (every year)Origin: Haymarket Affair, ChicagoYear: 1886Demand: 8-hour working dayStatus: International Labour Day / Workers’ DayLast verified on 11-06-2026', 0, 0, 0, 1790965659564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_81b194735a58f56d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '“Eskimos” are the primitive people living in?', '{"A":"North America","B":"Western Europe","C":"Central Asia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eskimos have traditionally lived in North America, especially Alaska and Northern Canada.They have also lived in Greenland, an Arctic island.Today, the term "Inuit" is preferred for many Indigenous groups in Canada and Greenland.They are traditionally adapted to the Arctic''s extremely cold climate.Their traditional occupations include hunting, fishing, and seal hunting.Last verified on 09-07-2026', 0, 0, 0, 1790965659564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_12c60b5dbf981427', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the currency of Canada?', '{"A":"Yen","B":"Rupee","C":"Dinar","D":"Dollar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Canada Capital is Ottawa.Canada Currency is Canadian Dollar.Canada official language is English; French.Canada located is in Continent North America.Canada Primary Religion is Christianity (But Secular Country).Canada Parliament called Parliament.Tricks for RememberDOLLAR Li-Ne-US-Ca-Fi-T-E-AMind trick: Li ne(a name) who lives in US likes Coffee(Ca- Fi) and Tea(T-E-A)**Li-Ne**Li-LiberiaNe-New Zealand**US**United States**Ca-Fi**Ca-CanadianFi- Fizzi**T-E-A**T-TaiwanE-EthiopiaA-AustraliaLast verified on 09-07-2026', 0, 0, 0, 1790965659564) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bfcaaf84ef19f346', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the purpose of the Marshall Plan in 1948?', '{"A":"Foreign aid to Western Europe / Rebuild war-torn European economies","B":"Economic assistance to Africa","C":"Recovery from WW1","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Marshall Plan (1948) was launched to provide economic aid for rebuilding the war-torn economies of Western Europe after World War II.It was signed into law on 3 April 1948 by Harry S. Truman.It was signed through the Economic Recovery Act of 1948.The plan was proposed in 1947 by George C. Marshall.It helped restore industry, infrastructure, and economic stability in Europe.Last verified on 08-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_11d2407012a98a73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The term Artificial Intelligence was invented by?', '{"A":"Albert Einstein","B":"John McCarthy","C":"Geoffrey Hinton","D":"Alan Turing","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John McCarthy is recognized as the father of Artificial Intelligence due to his astounding contribution in the field of Computer Science.John McCarthy was an American computer scientistNote: Artificial Intelligence is a branch of Computer science, which aims to create intelligent machines so that machine can think intelligently in the same manner as a human does.', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_39140193a1fa6d20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Dr. Abdul Salam won the Nobel Prize for the subject of _____?', '{"A":"Biology","B":"Chemistry","C":"Mathematics","D":"Physics"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr. Abdus Salam won the Nobel Prize in Physics in 1979.He received the award for his contribution to the Electroweak Theory, which unified the electromagnetic and weak nuclear forces.Additional information:Born: 29 January 1926, Jhang, PunjabDied: 21 November 1996Ph.D.: 1952, Theoretical Physics, University of CambridgeAchievement: First Pakistani Nobel laureate and second Muslim Nobel laureateLast verified on 06-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_95ba19ab9008bd3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which city is known as Pink City?', '{"A":"Allahabad","B":"Jaipur","C":"Shimla","D":"Jamnagar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jaipur is known as the "Pink City" of India.It is the capital of Rajasthan.The city was painted pink in 1876 to welcome the Albert Edward, the Prince of Wales.The distinctive pink-colored buildings became the city''s famous identity.Last verified on 06-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_de85ec59e8ed88d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the Currency of Cuba?', '{"A":"Quetzal","B":"Guyanese Dollar","C":"Cuban Peso","D":"Ghanaian Cedi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cuba Currency is Cuban Peso.Cuba Capital is Havana.Cuba official language is Spanish.Cuba located is in Continent North America.Cuba Primary Religion is Christianity.Cuba Parliament called National Assembly Of People’s Power.Tricks for RememberPESO M-A-C C-P-UMindTrick : just like MAC intosh…Cpu**MAC**M-MexicoA-ArgentinaC-Chile**CPU**C-ColumbiaP-PhilipinesU-UruguayLast verified on 03-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8d030ca57c2d64a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Abul Qasim Ferdowsi was a persian by _______ profession.', '{"A":"Astronomer","B":"Poet","C":"Chemist","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Al-Qasim Ferdowsi was a Persian poet.He is best known for writing the epic poem "Shahnameh" (Book of Kings).The Shahnameh was completed around 1010 AD.It contains about 60,000 couplets.Ferdowsi served as the court poet of Mahmud of Ghazni.Last verified on 03-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_07a0efabc6773137', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'On every 10th December, the Noble Peace Prize is awarded in ______?', '{"A":"Sweden","B":"Rome","C":"Norway","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nobel Peace Prize is awarded every year on 10 December in Oslo, Norway.The ceremony is held at Oslo City Hall.10 December marks the anniversary of the death of Alfred Nobel in 1896.The Peace Prize is the only Nobel Prize awarded in Norway.Physics, Chemistry, Literature, Physiology or Medicine Prizes: Stockholm, SwedenLast verified on 03-07-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0e919ae7738a9d1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'RCD (Regional Cooperation for Development) was established on _____?', '{"A":"21 July, 1964","B":"21 May, 1964","C":"21 August, 1964","D":"21 June, 1964"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Established On: 21 July 1964Founding Members: Pakistan, Iran, Turkey (3 countries)Successor Organization: ECO (1985)Purpose: Economic, technical, and cultural cooperationHeadquarters (later ECO): Tehran, IranLast verified on 17-01-2026', 0, 0, 0, 1790965659741) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ddde71931742d210', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the name of the Atomic Bomb that dropped on the City of Nagasaki?', '{"A":"Little Boy","B":"Fat Man","C":"Little Man","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Fat Man was dropped on Nagasaki, Japan.On August 9, 1945, at 11:01 AM.Additional information:The Little Boy type of bomb was dropped on the Hiroshima, Japan.On 6 August 1945 during World War II.Hiroshima deaths: around 40000 Nagasaki deaths: around 80000Last verified on 02-07-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d5ccd991516ae2e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'A little boy was dropped in which city?', '{"A":"Tokyo","B":"Nagasaki","C":"Hiroshima","D":"Kyoto"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Little Boy type of bomb was dropped on the Hiroshima, Japan.On 6 August 1945 during World War II.Additional information:The Fat Man was dropped on Nagasaki, Japan.On August 9, 1945, at 11:01 AM.Hiroshima deaths: around 40000 Nagasaki deaths: around 80000Last verified on 02-07-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cdc6ce0d5f8b2896', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the currency of Brazil?', '{"A":"Brazilian Dinar","B":"Brazilian  Rupee","C":"Brazilian  Yen","D":"Brazilian  Real"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brazil''s Currency is Real.Symbol: R$Currency Code: BRLBrazil Capital is Brasilia. Brazil''s official language is Portuguese. Brazil located is in the Continent of South America. Brazil''s Primary Religion is Christianity. Brazil Head of Govt. is President – Luiz Inacio Lula da SilvaBrazil''s Parliament is called the National Congress. Tricks for RememberLast verified on 02-07-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
