INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_35d0f7922992f11f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '22 March is observed internationally as?', '{"A":"Women''s Day","B":"World Water Day","C":"World Health Day","D":"Human Rights Day"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World Water Day is observed every year on 22 March.Additional information:First Observed: 22 March 1993Organized by: United Nations (UN)Theme 2021: ''Valuing Water''Theme 2022: "Groundwater, making the invisible visible".Theme 2023: Accelerating ChangeTheme 2024: Leveraging Water for PeaceTheme 2025: Glacier PreservationTheme 2026: Water and Gender: Where water flows, equality growsLast verified on 30-06-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_59d6973009531354', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When the Soviet Union (USSR) invaded Afghanistan?', '{"A":"24 December 1979","B":"24 December 1977","C":"24 December 1974","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of invasion: 24 December 1979Afghan President (at invasion): Hafizullah AminNew President installed: Babrak KarmalWar duration: 1979–1989Invading country: Soviet Union (USSR)Last verified on 18-01-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3717e5b8512fda34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The term Inflation means that money?', '{"A":"Increase in prices","B":"Falls in purchase in value","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inflation means a rise in prices and a fall in the value of money.It reduces the purchasing power of money over time.With inflation, the same amount of money buys fewer goods and services.Last verified on 16-06-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_908e19981437ea34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the Colour of UN Flag?', '{"A":"Blue and White","B":"Red and Blue","C":"White and Green","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The UN flag is blue and white in color.It was officially adopted in October 1947 by the United Nations General Assembly.The light blue color is known as “UN Blue”, symbolizing peace.The white emblem represents unity of all nations.It reflects the UN’s goal of maintaining global peace and security.Last verified on 25-06-2026', 0, 0, 0, 1790965659892) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c001a05d5d7bd05c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Elon Musk is the owner of which companies?', '{"A":"Apple and Amazon","B":"Tesla and SpaceX","C":"Facebook and Google","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elon Musk is the owner/CEO of Tesla and SpaceX.Tesla (Electric cars, energy) SpaceX (Space exploration).Additional information:X (Twitter)Neuralink (Brain-computer tech)The Boring Company (tunnels & transport)Last verified on 24-06-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b38b362faea952a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the tallest building in the world?', '{"A":"Merdeka 118","B":"Burj Khalifa","C":"Shanghai Tower","D":"Abraj Al-Bait Clock Tower"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of the tallest buildings in the world.RankNameCityCountryHeight[13]FloorsYear1Burj KhalifaDubai United Arab Emirates828163 (+ 1 below ground)20102Merdeka 118Kuala Lumpur Malaysia678.9118 (+ 5 below ground)20223Shanghai TowerShanghai China632128 (+ 5 below ground)20154Abraj Al-Bait Clock TowerMecca Saudi Arabia601120 (+ 3 below ground)20125Ping An International Finance CentreShenzhen China599.1115 (+ 5 below ground)2017Last verified on 07-03-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9fc0a461b3cf08ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Daughter of East was written by?', '{"A":"Fatima Jinnah","B":"Benazir Bhutto","C":"Ghanwa Bhutto","D":"Begum Raina Liaqat Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Benazir BhuttoBook Type: AutobiographyPublished: 7th January 1989Publisher: Simon & SchusterTheme: Politics, struggle, democracyAdditional information:Benazir Bhutto was the first female Prime Minister of Pakistan.She served two non-consecutive terms: 1988–1990 and 1993–1996.Last verified on 20-06-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_40c9887974410860', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"Jinnah of Pakistan" written by?', '{"A":"Stanly Wolpert","B":"Hector Bolitho","C":"Philip Hitti","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Jinnah of Pakistan" was written by Stanley Wolpert.It was published in 1984.The book is a famous biography of Muhammad Ali Jinnah, covering his public and private life.It describes Jinnah’s journey from his birth in 1876 to his death in 1948.Stanley Wolpert was an American historian known for his works on South Asian history.Last verified on 20-06-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_86593ec734188a03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Moho discontinuity is found between?', '{"A":"Inner core and outer core","B":"Crust and Mantle","C":"Upper mantle and lower mantle","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Moho discontinuity is the boundary between the Earth’s crust and mantle.It was discovered by seismologist Andrija Mohorovičić in 1909.It is identified by a sudden change in seismic wave speed.The crust is solid outer layer, while the mantle lies beneath it.Depth varies from 5–70 km depending on land or ocean area.Last verified on 02-04-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b2ddc33ba03f013f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When did the II World War (Second World War) Started?', '{"A":"1914","B":"1918","C":"1935","D":"1939"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World War II: Global war, 1939–1945.Little Boy: Dropped on Hiroshima, 6 August 1945.Fat Man: Dropped on Nagasaki, 9 August 1945, 11:01 AM.Additional information:World War I: Global war in Europe, 28 July 1914 – 11 November 1918.Last verified on 17-05-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f1235d872f7e614a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Through which pas, Karakorum highway (Shahrah-e-Resham) connects Pakistan with China?', '{"A":"Khunjerab Pass","B":"Khyber Pass","C":"Tochi Pass","D":"Gomal Pass"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahrah-e-Resham (Karakoram Highway) connects Pakistan and China through Khunjerab Pass.It is the highest paved international road in the world.It links Hassan Abdal (Pakistan) with Kashgar (China).It passes through the Karakoram mountain range.It is a symbol of strong Pakistan–China friendship.Additional information:The highway is also known as the Karakoram Highway (N-35).It was completed in 1979.Its total length is about 1,300 km.It is often called the “Eighth Wonder of the World” due to its difficult terrain.Last verified on 17-05-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b94aa870cf526fb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following cities is known as the City of Seven Hills?', '{"A":"Istanbol","B":"Rome","C":"Athenes","D":"Lisbon"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rome is the capital city of Italy.Rome is known as the “City of Seven Hills.”Palatine Hill (original settlement of Romulus)Capitoline HillQuirinal HillViminal HillEsquiline HillCaelian HillAventine HillLast verified on 01-04-2026', 0, 0, 0, 1790965660063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7bfe2d959e482747', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Petrograd and Leningrad are old names of which city?', '{"A":"Moscow","B":"St. Petersburg","C":"Warsaw","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation St. Petersburg (سینٹ پیٹرز برگ) is a major city in Russia.It was originally named St. Petersburg, renamed Petrograd in 1914 during World War I.Later, in 1924, it was renamed Leningrad in honor of Vladimir Lenin.After the fall of the Soviet Union in 1991, it reverted to its original name St. Petersburg.Last verified on 01-04-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_31546821121b06de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Hazrat Sulaiman (AS) founded the following mosque?', '{"A":"Al-Aqsa","B":"Al-Kartaba","C":"Blue Mosque","D":"Masjid Hanifia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sulaiman is associated with the construction and expansion of Al-Aqsa Mosque.Al-Aqsa Mosque is one of the holiest sites in Islam after Masjid al-Haram.It is located in Jerusalem (Bait-ul-Maqdis).It is believed that many prophets prayed in this sacred place.He was the son of Hazrat Dawood (A.S).He was gifted with the ability to communicate with animals and control Jinns.Last verified on 26-04-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3ce8eb5f3c5e6e8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The book "Great Tragedy" was written by?', '{"A":"Safdar Mehmood","B":"G.Allance","C":"Ameer Ali","D":"Z.A Bhutto"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book "The Great Tragedy" was written by Zulfikar Ali Bhutto (Z.A. Bhutto).Published: 1971Topic: 1971 political crisis / East Pakistan separationLanguage: EnglishLast verified on 10-06-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_80cd1935d0c0eb09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Habsha is the old name of ___?', '{"A":"Damascus","B":"Ethiopia","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Habsha is the historic name for Ethiopia.It is located in the Horn of Africa.The Migration to Abyssinia, also known as the First Hegira.Last verified on 19-03-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7cda7befcf5f5aff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Warsaw pact was signed in which year?', '{"A":"1950","B":"1955","C":"1960","D":"1965"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Signed: 14 May 1955Headquarters: Moscow, USSR (now Russia)Members: USSR + 7 countriesType: Military defense alliancePurpose: Counter NATO (North Atlantic Treaty Organization)Last verified on 10-06-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_eed25a68fa0bd1e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Financial Action Task Force (FATF), an international intergovernmental organization was established in Paris to stop ______?', '{"A":"Money Laundering","B":"Human Trafficking","C":"Drug Smuggling","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FATF (Financial Action Task Force):Headquarters: Paris, FrancePurpose: To combat money laundering and terrorism financing / Financial regulations and anti-money launderingOfficial Languages: English & FrenchFull Member Countries: 37Full Member Organizations: 2Total Members: 39Last verified on 10-03-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_98391c68800c6cc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the official language of Brazil?', '{"A":"Spanish","B":"English","C":"Portuguese","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brazil''s Currency is Real.Brazil Capital is Brasilia.Brazil''s official language is Portuguese.Brazil located is in the Continent of South America.Brazil''s Primary Religion is Christianity.Brazil Head of Govt. is President – Luiz Inacio Lula da SilvaBrazil''s Parliament is called the National Congress.Last verified on 06-06-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d381cf9b74c1995d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'MOSAD is the secret agency of?', '{"A":"Isreal","B":"USA","C":"China","D":"Russia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mossad is the national intelligence and secret agency of Israel.It is officially known as the Institute for Intelligence and Special Operations.Mossad was established on 13 December 1949.It plays a key role in intelligence gathering and covert operations.Its headquarters is located in Tel Aviv, Israel.Last verified on 03-06-2026', 0, 0, 0, 1790965660193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a4cd4261fb724204', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The book ''A Brief History of Time'' is written by ____?', '{"A":"Stephen Hawking","B":"Aristotle","C":"Oswald Spengler","D":"Karl Marx"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Stephen HawkingBook Title: A Brief History of TimeMain Topic: Universe (origin, structure, evolution, and fate)First Published: 1988Publisher: Bantam Dell Publishing GroupCopies Sold: ~10 millionLanguages: 40 languagesLast verified on 01-06-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ffb25e9661dc05a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the Circumference of Earth?', '{"A":"450,000 km","B":"50,075 km","C":"40,075 km","D":"30,000 km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth’s circumference at the equator is about 40,075 km (24,901 miles).Measured through the poles, it is slightly smaller: 40,008 km (24,860 miles).The difference is due to the equatorial bulge caused by Earth''s rotation.Diameter: ~12,756 km (7,926 miles).Age of Earth: ~4.453 billion years.Last verified on 31-03-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_40c1563b2711de07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In which year the next leap year would be observed?', '{"A":"2022","B":"2023","C":"2025","D":"2028"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The next leap year after recent cycle is 2028.A leap year comes after every 4 years.A year divisible by 4 is usually a leap.It has 366 days instead of 365 days.The extra day is added in February (29th February).Last verified on 01-06-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_011f7e026c31ba87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Where was Albert Einstein born?', '{"A":"Uk","B":"USA","C":"Germany","D":"Albania"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Einstein was born in Germany, on March 14, 1879.He died on 18 April 1955 (aged 76) in the U.S.He is one of the most influential physicists of the 20th century.In 1905, he published four landmark papers in physics.Last verified on 01-06-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3321ba2c35990020', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Estonia Latvia and Lithuania are known as what?', '{"A":"Pacific States","B":"Baltic States","C":"Atlantic States","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Estonia, Latvia, and Lithuania are three countries in Northern Europe.These countries lie along the Baltic Sea region.They share historical, cultural, and geographical similarities.Together, they are known as the Baltic States.Last verified on 30-05-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b51a9ea403c51b18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which one of the following World''s busiest Airport?', '{"A":"Benzair Airport","B":"Hartsfield-Jackson Atlanta International Airport (ATL)","C":"Hong kong International Airport","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atlanta''s Hartsfield-Jackson International Airport is the world''s busiest airport.It handling over 106 million passengers.It is located in Atlanta, Georgia, United States.It was opened on September 15, 1926.Number of runways: 5Last verified on 26-05-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f9dfffde0a9f9f6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Microsoft corporation is founded by _______?', '{"A":"Billgates","B":"Paul Allen","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microsoft was founded on April 4, 1975.It was founded by Bill Gates and Paul. Allen in Albuquerque, New Mexico.Last verified on 02-03-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2e8946a3dcbb0cfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Instrument used for measuring the thickness/purity of milk is called what?', '{"A":"Lucimeter","B":"Lactometer","C":"Barometer","D":"Hydrometer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lactometer is used to measure the purity and density (thickness) of milk.It checks if milk has been adulterated with water by measuring specific gravity.Works on the principle of buoyancy.Pure milk specific gravity: 1.028–1.032 at 15°CLast verified on 16-03-2026', 0, 0, 0, 1790965660333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_50dd2cd3460cbcfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'People''s Republic of China was founded in ______?', '{"A":"1947","B":"1948","C":"1949","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The People''s Republic of China was founded on 1 October 1949.It was established after the victory of the Communist Party in the Chinese Civil War.Mao Zedong announced its foundation in Beijing.This marked the end of the Republic of China government on the mainland.Beijing was declared the capital of the new state.Last verified on 17-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b6a60d57a96931b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Islamic revolution in Iran took place in?', '{"A":"February 1977","B":"February 1978","C":"February 1979","D":"February 1980"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Islamic Revolution in Iran took place in 1979.It overthrew the rule of Shah Mohammad Reza Pahlavi.The revolution was led by Ruhollah Khomeini.It is also called the Iranian Revolution of 1979.Additional information:Shah Mohammad Reza Pahlavi left Iran on 16 January 1979.Ayatollah Khomeini returned to Iran on 1 February 1979.The monarchy officially ended on 11 February 1979.Iran became an Islamic Republic after a referendum on 1 April 1979.Last verified on 17-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a91914fa31cb4fde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Tower of Silence is?', '{"A":"Cementry in London built in the memory of second World war","B":"Place where dead remains of flowers of Zoroastrain are placed after funeral rituals","C":"Another name of Eiffel Tower","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tower of Silence is a burial place used in the Zoroastrian religion.It is used to place dead bodies after funeral rituals.The practice is known as “sky burial” in Zoroastrian tradition.It is mainly found in India and Iran.Last verified on 17-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0680f13c6672f5d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Snow line refers ______?', '{"A":"Melting snow","B":"Perpetual snow","C":"Deep cold water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The snow line is also known as the snow level or snow boundary.It refers to the elevation or altitude above which snow remains on the ground for a significant part of the year, often perpetually.It marks the boundary between the area where snow melts completely during the summer and the area where snow remains year-round.Last verified on 17-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fd6c75151c6c5d23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The purpose of International Monetary Fund is to _____?', '{"A":"Promote International Trade","B":"Maintain stable exchange rate","C":"Help economically backward countries","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The International Monetary Fund (IMF) was created to ensure global financial stability.Its main purpose is to maintain stable exchange rates and support international economic cooperation.It also helps countries facing economic difficulties.Additional information:IMF was established in 1944 (Bretton Woods Conference).Headquarters: Washington, D.C., USAMember countries: 190+ countriesLast verified on 10-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4b05fb9a98527461', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Black pole is a seaport and resort in _____?', '{"A":"Germany","B":"France","C":"England","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blackpool is a famous seaport and tourist resort in England.Located on the northwest coast of England along the Irish Sea.Known for its beaches, amusement parks, and the Blackpool Tower.Additional information:Popular for annual illuminations and tourism.One of the major holiday destinations in the UK.Famous landmarks include Blackpool Pleasure Beach.Last verified on 10-05-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d0d65d6bb61232de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When is Nakba Day observed?', '{"A":"May 10","B":"May 12","C":"May 14","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Israel became a state on May 14, 1948.78 percent of Palestine was captured by Israel in 1948The word ‘Nakba’ means سانحہ، واقعہ، حادثہ یا تباہیNakba day is observed on 15 May*****', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a0000b184e7ce332', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Sun has temperature of around _____?', '{"A":"3000 °C","B":"6000 °C","C":"4000 °C","D":"5000 °C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sun is a star at the center of our solar system with a surface temperature of about 6000 °C (Sun’s core is even hotter, ~15 million °C).It provides light and heat, essential for life on Earth.The Sun’s energy drives weather, photosynthesis, and climate.Last verified on 18-03-2026', 0, 0, 0, 1790965660484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_aabff29a64dc3150', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Father of former US Secretary of State Madeleine Albright was also a member of UN Commission on India-Pakistan and author of the book “Danger in Kashmir”. What was his name?', '{"A":"Josef Albright","B":"Josef Korbel","C":"Owen Dixon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Josef Korbel was the father of Madeleine Albright.He served in the UN Commission on India and Pakistan (UNIP).He also wrote the book Danger in Kashmir.Last verified on 01-05-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9f5945604f2f3d81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"Shahnama" was written by _____?', '{"A":"Firdausi","B":"Al- Beruni","C":"Ameer Khusro","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Shahnama" is an epic poem that was written in 1010.It contains about 60,000 couplets.The author of "Shahnama" was Abu Al-Qasim Firdausi.The epic poem is also known as the "Book of Kings".Last verified on 30-03-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0e748883a129d487', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the currency of Saudi Arabia?', '{"A":"Dollar","B":"Euro","C":"Rupee","D":"Riyal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Saudi riyal is the currency of Saudi Arabia.Symbol: code: SARIt is subdivided into 100 halalas (Arabic: هللة Halalah).On February 20, 2025, the Saudi Central Bank announced the approval of the Saudi riyal symbol by King SalmanAdditional informationThe capital of is Riyadh.The official language is Arabic.It is located in the continent of Asia.Primary Religion is Islam.Parliament, called Majlis Al Shura.Last updated by NA on 27 April 2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ebac2171ca1e32d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the name of the sacred book of Zoroastrianism?', '{"A":"Vedas","B":"Zend Avesta","C":"Upanishads","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sacred book of Zoroastrianism is the Zend Avesta (Avesta).It contains teachings of the prophet Zoroaster (Zarathustra).It focuses on the concept of good vs evil (Ahura Mazda vs Angra Mainyu).It is one of the oldest religious texts in the world.It was originally written in the Avestan language.Last verified on 27-04-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fd8bc66f382fe06a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The famous book Al Qanoon Fi Tib was written by _____?', '{"A":"Abdul Qasim","B":"Jabir bin Hayan","C":"Zakariya Al-Razi","D":"Abu Ali  Sina"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The famous book "Al-Qanun" (The Canon of Medicine) was written by Abu Ali Sina.It is also known as Avicenna. The book covers medicine, diseases, and treatments.Last verified on 27-04-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_52ed8a67234789df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the meaning of Vishnu?', '{"A":"The preserver","B":"The helper","C":"The destroyer","D":"The creator"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vishnu is one of the major deities in Hinduism.He is known as the Preserver (Protector of the Universe).He maintains balance and order in the world (Dharma).He is part of the Hindu Trinity (Trimurti).The other two are Brahma (Creator) and Shiva (Destroyer).Last verified on 27-04-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3d27e3bebbc4fe0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the coldest city in the world?', '{"A":"Antractica","B":"Yakutsk","C":"Alaska","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yakutsk is considered the coldest city in the world.It is located in Siberia, Russia.Temperatures can drop below -40°C to -50°C in winter.Despite extreme cold, it has a stable population.It is built on continuous permafrost (frozen ground).Last verified on 27-04-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_961ae99523292ca4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'How many parts are in the book "Seerat-u-Nabi" by Shibli and Suleman Nadvi?', '{"A":"5","B":"4","C":"7","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seerat-u-Nabi is a famous biography of the Prophet (PBUH).It was started by Shibli Nomani.Later completed by Suleman Nadvi.The complete work consists of 7 volumes (parts).It is one of the most authentic and detailed Seerat books.Last verified on 18-05-2026', 0, 0, 0, 1790965660617) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f27b61c29d3f5569', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the old name of Ethiopia?', '{"A":"Abbasinya","B":"Andorra","C":"Mesopotamia","D":"Constantinople"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The old name of Ethiopia was AbyssiniaLandlocked country on the Horn of Africa.Capital is Addis Ababa.Currency is the Birr.The official language is Amharic.Located in the Continent of Africa.Primary Religion is Islam and Christianity.Head of Govt is Prime Minister Abiy Ahmed.Parliament is called the Federal Council and the House of Representatives.Last updated by NS on 20-April-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_caf07ddf272a4aca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Grand Mosque at Damascus was built by?', '{"A":"Umar bin Abdul Aziz","B":"Walid bin Abdul Malik","C":"Abdul Malik","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Mosque of Damascus is also known as the Umayyad Mosque.It was built by the Umayyad Caliph al-Walīd I between 705 and 715 CE.It is located in the old city of Damascus.It is the capital of Syria.It is one of the largest and oldest mosques in the world.The mosque opened in 715 AD.Last verified 25-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b6a2f16ef7b15460', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which city was once known as Constantinople?', '{"A":"Cairo","B":"Qum","C":"Istanbul","D":"California"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constantinople was the former name of Istanbul, Turkey. It was renamed Istanbul in 1930 after the fall of the Ottoman Empire.Last verified on 25-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_76f31002b350e916', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The currency of Egypt is ______?', '{"A":"Afghani","B":"Shekel","C":"Rufia","D":"Pound"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Egyptian pound is the official currency of Egypt.Currency Code: EGP (Egyptian Pound)Symbol: E£, £E, or LESubunit: 100 piastres Additional informationThe capital is Cairo.The official language is Arabic.Located is in the continent of Africa/ Asia.The primary religion is Islam.Parliament is called the People’s Assembly. Tricks for Remember POUND S-E-S-U Mind Trick : Sheshu(a name) plays in the Pond. **S-E-S-U** S - South Sudan E - Egypt S - Syria U - UK', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_00df5386d84d7915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Opium War was fought between China and _____?', '{"A":"French","B":"British","C":"Indian","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Opium Wars were fought between Britain and China in the 19th century.Britain wanted to force China to allow opium trade from India.The wars led to unequal treaties and loss of Chinese territory.Additional information:First Opium War: 1839–1842Second Opium War: 1856–1860Treaty of Nanking ceded Hong Kong to Britain.Last verified on 03-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8666faf5668db0be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In which month does the UN General Assembly usually meet every year?', '{"A":"November","B":"October","C":"September","D":"August"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The General Assembly is the largest organ of the United Nations.It is located in New York, USA.The UN General Assembly usually meets every year in September.There are six main organs of the UN.The official languages are Arabic, Chinese, English, French, Russian, and Spanish, with English and French as the working languages of the Secretariat.Founded: October 24, 1945, in San Francisco, California, USAHeadquarters: New York, USAFounders: United States, India, United Kingdom, Brazil, FranceLast verified on 02-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5a385473eae01aef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Isaac Newton gave?', '{"A":"Laws of motion and laws of gravition","B":"Laws of Geometary","C":"Laws planetary motion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isaac Newton (1642–1727) was an English physicist and mathematician.He formulated the laws of motion and law of universal gravitation.His work laid the foundation for classical mechanics.Last verified on 02-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_74cc7f51556a0376', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Broadway street is famous for _____?', '{"A":"Banking","B":"Stock exchange","C":"Cinema halls","D":"Shopping centers"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Broadway is a famous street in New York City, USA.It is globally known for its theatre and entertainment industry.Broadway became a major center for stage plays and cinema during Hollywood’s golden age.It is especially associated with live theatre performances and movie palaces.Last verified on 01-04-2026', 0, 0, 0, 1790965660728) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f59e4eb9e77f5b02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Morocco and Spain are separated by _____?', '{"A":"River Danube","B":"Palk Strait","C":"Strait of Gibraltar","D":"Red Sea"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Morocco (مراکش) and Spain (سپین) are separated by the Strait of Gibraltar.It is a narrow strait connecting the Atlantic Ocean with the Mediterranean Sea.The strait has a minimum width of about 13 km (8 miles).Named after the Rock of Gibraltar, it is a major international shipping route.Last verified on 01-04-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2224a0953757cd04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following rivers run through Paris? The Seine, The Thames, The Rhine, The Danube', '{"A":"The Seine","B":"The Thames","C":"The Rhine","D":"The Danube"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Seine River runs through Paris, France.It dividing the city into the Right Bank (Rive Droite) and Left Bank (Rive Gauche).It is a 777-kilometre-long (483 mi) river in northern France.There are 37 bridges in Paris across the Seine.Last verified on 01-04-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e866cbe185bf5d7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Jabir bin Hayyan was famous Muslim?', '{"A":"Physicist","B":"Chemist","C":"Discoverer","D":"Teacher"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jabir ibn Hayyan, known as the "father of chemistry."He was an Arab Chemist.Composition of Alchemy was written by Jabir Bin Hayyan.Notable ideas:Use of organic substances in chemistrySulfur-mercury theory of metals Science of the balance Science of artificial generationLast verified on 07-02-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_10cead9df21aacb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which language is predominantly spoken in Qatar?', '{"A":"Persian","B":"German","C":"Arabic","D":"English"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qatar Capital is Doha.Qatar Currency is Qatari Riyal.Qatar official language is Arabic.Qatar located is in Continent Asia.Qatar Primary Religion is Islam.Qatar Head of Govt. is Prime Minister – Khalid bin Khalifa bin Abdul Aziz Al Thani.Qatar Parliament called .Tricks for RememberLast verified on 01-04-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7b603b4cb7373adb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which sport is also called as ''Ping pong''?', '{"A":"Cricket","B":"Football","C":"Volleyball","D":"Table tennis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name Table Tennis was officially adopted in 1921–22.It replaced the earlier popular name “Ping-Pong.”The original Ping-Pong Association (1902) was revived at that time.After revival, the sport was standardized and renamed.Last verified on 31-03-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_58ea6a053bfbacc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Pele was an athlete of which game?', '{"A":"Cricket","B":"Tennis","C":"Football","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pele was a legendary Brazilian football player known for his incredible goal-scoring skills.He won three FIFA World Cups (1958, 1962, 1970) — a record unbeaten to this day.Last verified on 30-03-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ad94bb58462a2449', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the size of a golf hole?', '{"A":"3.5 inches","B":"4.25 inches","C":"4 inches","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The official diameter of a golf hole is 4.25 inches, as set by the Rules of Golf.This standard has been in place since 1891.Last verified on 30-03-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_caa9ff0c86246179', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Universal Declaration of Human Rights (UDHR) is a milestone document adopted on _____?', '{"A":"10 March 1949 by General Assembly Resolution 217 A (III)","B":"15 March 1948 by General Assembly Resolution 217 A (III)","C":"10 December 1948 by General Assembly Resolution 217 A (III)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Universal Declaration of Human Rights (UDHR) is a milestone document adopted on 10 December 1948 by General Assembly Resolution 217 A (III).Additional information:Drafted by: Eleanor Roosevelt (Chair of UN Human Rights Commission)Total Articles: 30 Articles outlining rights like freedom, equality, and protection from discriminationHeadquarters of UN: New York, USASignificance: Basis for international human rights law and national constitutionsLast verified on 19-03-2026', 0, 0, 0, 1790965660852) ON CONFLICT(id) DO NOTHING;
