INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c8a32eedf5827230', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Where was Gautama Buddha born?', '{"A":"Bodh Gaya, India","B":"Lumbini, Nepal","C":"Sarnath, India","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gautam Budha was born in Lumbini, Nepal in 623 BC.Language of discourse/lectures of Budhha was: Pali He was the founder of Buddhism.Last verified on 16-03-2026', 0, 0, 0, 1790965661050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ebf52fe706a3b55e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Days and nights are formed due to _____?', '{"A":"Earth’s revolution","B":"Earth’s rotation on its axis","C":"Earth’s rotation accompanied with its revolution","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth revolves around the Sun.It is rotates on its own axis.The Earth''s rotation causes day and night.One complete rotation takes 24 hours.Last verified on 16-03-2026', 0, 0, 0, 1790965661050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_488d8bd60e312580', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the old name of Iran?', '{"A":"Anatolia","B":"Persia","C":"Rangon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The old name of Iran was Persia.In 1935, Reza Shah Pahlavi requested other countries to use the name Iran officially.The word Iran means “Land of the Aryans.”Last verified on 14-03-2026', 0, 0, 0, 1790965661050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_453be27bf196df17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Nowruz Festival is celebrated in _____?', '{"A":"September 21","B":"March 21","C":"June 21","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nowruz (Navroz) is the Persian New Year festival celebrated in Iran, Central Asia, and some other regions.It usually falls on 21 March each year.It marks the arrival of spring and the spring equinox.Additional information:Main countries celebrating: Iran, Afghanistan, Azerbaijan, Tajikistan, UzbekistanThe festival has been celebrated for over 3,000 years.Nowruz was recognized by UNESCO as an Intangible Cultural Heritage in 2009.The United Nations declared 21 March as International Nowruz Day in 2010.Last verified on 14-03-2026', 0, 0, 0, 1790965661050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_33acdc950708c66a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'TV (Television) was invented by _______?', '{"A":"Johannes Kepler","B":"Nicolaus Copernicus","C":"John Logie Baird","D":"Marconi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Logie Baird, a Scottish engineer, is credited with inventing the first working television system.He successfully demonstrated the mechanical television on 26 January 1926 in London.Last verified on 13-03-2026', 0, 0, 0, 1790965661051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7372ad6a6157502b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Einstein was awarded the Nobel Prize for his work on:', '{"A":"Theory of the photoelectric effect","B":"General theory of relativity","C":"Special theory of relativity","D":"Invention of Electric Motor","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Einstein received the Nobel Prize for his discovery of the Law of the photoelectric effectThe 1921 prize was actually awarded in 1922.', 0, 0, 0, 1790965661051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bf37a5992902ba0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the Currency of Oman?', '{"A":"Omani Rial","B":"Omani Dirham","C":"Omani Dollar","D":"Omani Dinar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oman Capital is Muscat.Oman Currency is Omani Rial.Oman official language is Arabic.Oman located is in Continent Asia.Oman Primary Religion is Islam.Norway Parliament called Monarch.Tricks for RememberLast verified on 11-03-2026', 0, 0, 0, 1790965661051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3afeefacadfbb720', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'McMahon line is a border between _______?', '{"A":"South Korea and North Korea","B":"Pakistan and India","C":"China and Myanmar","D":"China and India"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The McMahon Line is the boundary line between China and India in the eastern Himalayas.It was proposed in 1914 during the Shimla Convention between British India and Tibet.China does not officially recognize this border.The line mainly separates India’s Arunachal Pradesh from Tibet (China).Additional information:Durand Line (1893) – Pakistan ↔ AfghanistanRadcliffe Line (1947) – India ↔ PakistanLine of Control (LOC) – India ↔ Pakistan (Kashmir ceasefire line)38th Parallel – North Korea ↔ South KoreaLast verified on 11-03-2026', 0, 0, 0, 1790965661255) ON CONFLICT(id) DO NOTHING;
