INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_567daa311140eda5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'New Deal was written by?', '{"A":"Theodore Roosevelt","B":"Franklin D. Roosevelt","C":"Herbert Hoover","D":"Woodrow Wilson"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Franklin D. Roosevelt wrote the New Deal The New Deal programs were primarily launched between 1933 and 1939', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_24118d3a087e6e9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is meant by “Equinox”?', '{"A":"The longest day","B":"The shortest day","C":"The sun-month long day","D":"Equal duration of day and night"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Equinox" means Equal duration of day and night.The time or date (twice each year) at which the sun crosses the celestial equator During the equinoxes, solar declination is 0°The September equinox is called the autumnal or fall equinox on 23 SeptemberThe March equinox is called the vernal or spring equinox on 19 March or as late as 21 March', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ece5b6efdaa76a81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"Wheel" is a symbol of ?', '{"A":"Prosperity","B":"Speed","C":"Progress","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The wheel is a powerful and universal symbol of progress, motion, innovation, and changeAdditional informationBlack flag: Symbol of protest Lower-level flag: Symbol of national mourning White flag: Symbol of treaty or dedicationRed triangle: Symbol of family planning Pigeon bird: Symbol of peaceRed light: Symbol of danger or stopping traffic', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9906ca7c189c3157', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Thomas Cup is associated with which game?', '{"A":"Squash","B":"Badminton","C":"Hockey","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Thomas Cup is associated with badminton.It is an international badminton competition among teams representing member nations (IBF)It was donated in 1939 by Sir George ThomasThe championship has been conducted every two years since 1982.', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3f9efbbf6985fdb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"Southern Cross" which is the constellation found in the southern region of the night sky consists of?', '{"A":"3 stars","B":"5 stars","C":"2 stars","D":"6 stars"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Southern Cross is also known as Crux.The constellation primarily consists of four bright stars that form a cross shape.The Four Main Stars:Alpha Crucis (Acrux): The brightest, at the bottom.Beta Crucis (Mimosa): Forms the crossbeam.Gamma Crucis (Gacrux): The northernmost star.Delta Crucis (Imai): Also part of the crossbeam. The Fifth Star:Epsilon Crucis (Ginan): Often added to complete the pattern, as seen on the flags of Australia, Brazil, and New Zealand,', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_369dc3b0a7d3e715', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The total distance of a Marathon race is _____?', '{"A":"42.105 km","B":"42.195 km","C":"42.294 km","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Marathon race is a long-distance running event standardized internationally.The official distance is 42.195 km (26.2 miles).Standardized at the 1908 London Olympics to start at Windsor Castle and finish in front of the royal box.Last verified on 20-01-2026', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_443970eaed7dfb89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following is NOT a cereal Crop? Cotton and Sugarcane, Wheat and Barley, Rice, Corn', '{"A":"Cotton and Sugarcane","B":"Wheat and Barley","C":"Rice","D":"Corn"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cereal crops are grown primarily for their edible grains.Examples: Wheat, Barley, Rice, Corn (Maize).Additional information:Cotton: Fiber crop, not a cereal.Sugarcane: Cash crop, grown for sugar production.Cereal crops are staple foods and form a major part of the human diet.Last verified on 19-02-2026', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f38cb72e652ab911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'KUNA is news agency of _____?', '{"A":"India","B":"China","C":"Kuwait","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Name: Kuwait News Agency (KUNA)Founded: 1956Headquarters: Kuwait City, KuwaitLanguages: Arabic, EnglishCoverage: Local, regional, and international newsAdditional information:Pakistan: Associated Press of Pakistan (APP)India: Press Trust of India (PTI)USA: Associated Press (AP)Britain: Reuters Syria: SANA (Syrian Arab News Agency)Last verified on 18-01-2026', 0, 0, 0, 1790965661840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_19590c77212f77d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'U2 incident took place in ______?', '{"A":"1950","B":"1955","C":"1960","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of Incident: 1 May 1960Location: Sverdlovsk region, Soviet UnionPilot: Francis Gary Powers (captured by USSR)Plane Altitude: Approximately 70,000 feet (21,300 meters)Impact on US-Soviet Relations: Cancelled the Paris Summit of 1960Additional information:Francis Gary Powers was later exchanged for Soviet spy Rudolf Abel in 1962.Last verified on 18-01-2026', 0, 0, 0, 1790965661990) ON CONFLICT(id) DO NOTHING;
