INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b3754edf0514d0f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In which year did the Bolsheviks Revolution take place in Russia?', '{"A":"1913","B":"1917","C":"1915","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Bolshevik Revolution took place in 1917.It overthrowing the Tsarist regime.It led to the establishment of the Soviet Union and Communist rule under Lenin.Additional Points:February 1917: The Tsar abdicated during the February Revolution.October 1917: Bolsheviks seized power in Petrograd (St. Petersburg).Last verified on 15-01-2026', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a5ad50a85a85742c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Dynamite was discovered by Alfred Nobel in 1867 in _______?', '{"A":"America","B":"Spain","C":"Sweden","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dynamite was invented by Alfred Nobel in the 1860s.Additional Information REKATED ALFRED NOBELHe was a chemist from Sweden. Full name: Alfred Bernhard NobelBorn: October 21, 1833, Stockholm, SwedenThe founder of the Nobel PrizeInvented Nitro-glycerine in 1875.Died: on December 10, 1896, in Sanremo, Italy', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6dc69767b35ca369', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"38th Parallel" is the boundary line between _____?', '{"A":"India and China","B":"North & South Korea","C":"Germany & South Korea","D":"India & Pakistan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 38th parallel is a name given to the latitude 38° N, which demarcates North Korea and South Korea.ADDITIONAL INFORMATION RELATED TO 38th parallel The line was demarcated by U.S. military planners at the PotsdamIt was established at the end of World War II.It is the symbol of the Cold War.It is a circle of latitude 38 degrees north of the equator.', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_702b97b4165b4b34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'China has a claim on part of Indian province of _____?', '{"A":"Himachal Pradesh","B":"United Province","C":"Arunachal Pradesh","D":"Madhya Pradesh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China claims part of the Indian province of Arunachal Pradesh, which it calls “South Tibet”.Additional information:Area Claimed by China: ~90,000 sq kmBorders: Shares boundary with China (Tibet) and BhutanWar: Sino-Indian War in 1962Capital of Arunachal Pradesh: ItanagarTotal Indian States with Border Disputes: 4 (Arunachal Pradesh, Jammu & Kashmir, Sikkim, Ladakh)Last Verified on 13-01-2026', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
