INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cb43ef791f522606', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Watergate scandal is related to ______?', '{"A":"Spying","B":"Terrorism issues","C":"Canal water issues","D":"Dam issues"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Watergate scandal was related to political spying in the United States.It involved the illegal break-in and surveillance of the Democratic Party headquarters.The scandal led to the resignation of President Richard Nixon in 1974.Last Verified on 13-01-2026', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fbb7983eb16ef80d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"The Wealth of Nation" was written by?', '{"A":"Adam Smith","B":"William Robins","C":"Ravid Recardo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adam Smith, an 18th-century Scottish philosopher.He is considered the father of modern economics.He is most famous for his work, "The Wealth of Nations".It published on 9 March 1776.During the Scottish Enlightenment and the Scottish Agricultural Revolution.Last Updated on 13-01-2026', 0, 0, 0, 1790965662192) ON CONFLICT(id) DO NOTHING;
