INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_45c0fb4886f3c5e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The world’s famous Madame Tussauds Museum is in _____?', '{"A":"New York","B":"Paris","C":"London","D":"Madrid","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Madame Tussauds is a wax museum.Madame Tussauds was founded in 1835.Founder French wax sculptor Marie TussaudLocated in London, England', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_15798a43890e1cb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The event of Boston Tea Party occured in _____?', '{"A":"1773","B":"1873","C":"1673","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Boston Tea Party occurred in 1773 in Boston, Massachusetts, USA.American colonists protested against British taxation on tea.They threw tea shipments into Boston Harbor as a form of resistance.Additional Details / FactsPart of the events leading to the American Revolution.Protest against the Tea Act imposed by Britain.Demonstrated early colonial unity against British rule.', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fc6649ccf658ab56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Communist Manifesto written by Karl Marx was originally written in _____?', '{"A":"Latin","B":"English","C":"German","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Communist Manifesto was written by Karl Marx and Friedrich Engels in 1848.It presents the principles of communism and critiques capitalism.It was originally written in German.Additional Details / FactsFirst published in LondonLater translated into English, French, Russian, and other languagesInfluenced political movements worldwide', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_93b9d463b88fd550', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Ceylon (now Sri Lanka) became a republic in _____?', '{"A":"1970","B":"1971","C":"1972","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ceylon changed its name to Sri Lanka and became a republic in 1972.Previously it was a British Dominion after gaining independence in 1948.The move marked full sovereignty and republican status.Additional Details / FactsCapital: Colombo (commercial), Sri Jayawardenepura Kotte (administrative)Official languages: Sinhala, TamilCurrency: Sri Lankan Rupee', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_312d36fef63c5940', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What was the name of Atomic Bomb dropped on the city of Hiroshima?', '{"A":"Little Girl","B":"Little Boy","C":"Fat Boy","D":"Little Man"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During World War II, Little Boy was a uranium-based atomic bomb dropped on Hiroshima, Japan.It exploded on 6 August 1945.It causing approximately 40,000 deaths immediately.Additional information:Fat Man (plutonium-based) was dropped on Nagasaki on 9 August 1945.It causing around 80,000 deaths.', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7d3d3ddab84250ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The International Dateline passes through the _____?', '{"A":"Malacca Strait","B":"Bering Strait","C":"Gibraltar Strait","D":"Florida Strait"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The International Date Line (IDL) is an imaginary line on the Earth’s surface.It runs roughly along the 180° longitude in the Pacific Ocean.It separates two consecutive calendar days.The Bering Strait, between Russia and Alaska.Additional Details / FactsCrossing it westward adds a day, eastward subtracts a day.', 0, 0, 0, 1790965662337) ON CONFLICT(id) DO NOTHING;
