INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_710c6fb3f89f935d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Marco Polo was a famous _____?', '{"A":"Writer","B":"Scientist","C":"Traveller","D":"Sportsman","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Marco Polo was a Venetian merchant, explorer, and writer who traveled through Asia along the Silk Road between 1271 and 1295The famous traveler “Marco Polo” belonged to ItalyMarco Polo was also nicknamed MilioneMarco Polo was born in 1254 in VeniceMarco Polo Died: on January 8, 1324, in Venice, Italythe Italian title of Marco Polo''s book was Il libro di Marco Polo detto il Milione, which means "The Book of Marco Polo"ND10-3-2023', 0, 0, 0, 1790965662473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ea7f3f592dd4b524', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Chennai is the new name of which Indian city?', '{"A":"Patna","B":"Madras","C":"Agra","D":"Lucknow"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chennai is the new name for the Indian city formerly known as Madras, The name officially changed in July 1996 by the Government of Tamil NaduThe city was established in 1639Official languages: Tamil, English', 0, 0, 0, 1790965662473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e60e187748930034', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'National income is essentially composed of ___', '{"A":"All wealth of a nation","B":"Annual Income of the central government","C":"All income of the people on a year","D":"Income derived from taxes by the central government"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "All wealth of a nation" relates to its total assets minus liabilities (net wealth) or its productive capacity (Gross Domestic Product/National Income)This can refer to the country''s total physical and financial assets minus its debts (national net wealth) or, in classical terms (Adam Smith''s Wealth of Nations), the annual flow of goods and services produced (Gross National Product/Income).', 0, 0, 0, 1790965662474) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_21962cd6a2ad9ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following categories of Nobel Prizes was not created by Swedish Scientist Alfred Nobel?', '{"A":"Peace","B":"Literature","C":"Economics","D":"None of thes"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alfred Nobel (a Swedish chemist) initiated Nobel Prize in:Peace PhysicsChemistryPhysiology or MedicineLiteratureIn 1901, Nobel Prize was first awarded in Stockholm, Sweden,expected the Peace Prize in Kristiania (now Oslo), Norway.****Nobel Prize in Economics started in 1968In 1968, Sveriges Riksbank (Sweden''s central bank) established the Prize in Economic Sciences in Memory of Alfred Nobel, founder of the Nobel PrizeND23-4-2023', 0, 0, 0, 1790965662474) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_38e274aabed0bfaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following UN agencies has received Noble Peace Prize?', '{"A":"ILO","B":"UNICEF","C":"UN High commission for Refugees","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ILO (International Labour Organization): Received the Nobel Peace Prize in 1969 for promoting social justice and better working conditions.UNICEF (United Nations International Children''s Emergency Fund): Awarded in 1965 for its work in aiding children and mothers in developing countries.UNHCR (United Nations High Commissioner for Refugees): Won the Nobel Peace Prize twice (in 1954 and 1981) for assisting refugees worldwide.', 0, 0, 0, 1790965662474) ON CONFLICT(id) DO NOTHING;
