INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d88df5880e90b782', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Reuters is the news agency of _______?', '{"A":"United States","B":"United Kingdom","C":"France","D":"Germany"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation News Agencies of Important CountriesPakistan: Associated Press of Pakistan (APP)China: XinhuaRussia: TASS (Telegrafnoye agentstvo Sovetskogo Soyuza) India: Press Trust of India (PTI)France: AFP (Agence France-Presse) (also oldest news agency)Italy: ANSA (Agenzia Nazionale Stampa Associata)USA: Associated Press (AP)Britain: Reuters Malaysia: Bernama Israel: ITIMBahrain: BNA (Bahrain News Agency)Iran: FARSSyria: SANA(Syrian Arab News Agency)Yemen: SABAIndonesia: Antara Kuwait: KUNA (Kuwait News Agency)Kenya: KNA (Kenya News Agency)', 0, 0, 0, 1790965663031) ON CONFLICT(id) DO NOTHING;
