INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3c07400cd704a994', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When did the Britain returned Hong Kong to China?', '{"A":"2000","B":"1997","C":"1959","D":"2008"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Britain handed Hong Kong back to China on July 1, 1997, under the "One Country, Two Systems" agreement.The transfer ended 156 years of British rule.It allowing Hong Kong to maintain a separate legal and economic system for 50 years.', 0, 0, 0, 1790965663146) ON CONFLICT(id) DO NOTHING;
