INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_49fe385dd690e534', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'As per Article 8 of the Statute of the International Court of Justice, The General Assembly and the Security Council shall proceed ______ to elect the members of the Court.', '{"A":"With mutual consensus","B":"Independently of one another","C":"In joint sitting","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 8 of the ICJ Statute provides that the General Assembly and Security Council elect judges independently.This ensures balance and prevents dominance of one organ over the election process.', 0, 0, 0, 1790965663881) ON CONFLICT(id) DO NOTHING;
