INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8243bbe9413a9538', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What divides the Earth into the Northern and the Southern Hemispheres?', '{"A":"South Pole","B":"Moon","C":"Equator","D":"North Pole"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Equator is an imaginary line that divides the Earth into the Northern and Southern Hemispheres.It lies at 0° latitude.It is equidistant from the North and South Poles.', 0, 0, 0, 1790965664081) ON CONFLICT(id) DO NOTHING;
