INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fd465e8f38d8948c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The title page of document is called ____?', '{"A":"Text page","B":"Cover page","C":"Both","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cover page is also known as a title page.It is the first page of a paper or report.It typically includes essential information such as the title, author(s), course name, instructor, date, and sometimes the institution''s name.', 0, 0, 0, 1790965664188) ON CONFLICT(id) DO NOTHING;
