INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7881b70e2556edfa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Philanthropists is also known as ______?', '{"A":"Politicians","B":"Athletes","C":"Humanitarians","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Philanthropists are individuals who seek to promote the welfare of others.It typically through charitable donations and actions, making them synonymous with humanitarians.', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8f2393c67ed5fc4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'According to Von Thunen Model the central place is _____?', '{"A":"Grains","B":"City","C":"Forest","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Von Thünen model explains agricultural land use patterns based on distance from a central market.Johann Heinrich von Thünen developed it, and it was first published in 1826.', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
