INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2ccc45ab0f5300ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Siddhartha was written by ____?', '{"A":"Herman Hesse","B":"Gotam Buddah","C":"Kishan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1922 novel by Hermann Hesse that deals with the spiritual journey of self-discovery of a man named Siddhartha during the time of the Gautam Buddha.', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5eaf5e78c02966d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which region of the world was declared "Free of Wild Polio" on 25th August 2020?', '{"A":"Africa","B":"South Asia","C":"East Asia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Africa is free from wild poliovirus, the World Health Organization (WHO) announced on 25 August By 2020, all three strains of the wild poliovirus (type 1, type 2, and type 3) have been eradicated in Africa.In 2020 two countries where the virus remains endemic, are Afghanistan and Pakistan.whileType 2 wild poliovirus was declared eradicated in September 2015. ND27-7-2023', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47f69691677ecff0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The book always has _____?', '{"A":"Page","B":"Ink","C":"Paper","D":"Story"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The logic is:1) Ink → Ink is related to pen 2) Page → The book always has page3) Paper → Paper is related to the tree.4) Story → Story is related to literature.', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_94a5de3b893f191a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The main export of Saudi Arabia is _____?', '{"A":"Crude oil","B":"Natural gas","C":"Dates","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saudi Arabia is the world''s largest exporter of crude oil.It is the backbone of its economy.Saudi Arabia imports machinery and equipment to support industrial growth and infrastructure development.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3b885c7fdc189368', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following presidents of America abolished slavery?', '{"A":"Abraham Lincoln","B":"Thomas Jefferson","C":"George Washington","D":"Stanley Jackson"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States criminalized the international slave trade: 1808Slavery was made unconstitutional: 1865Note: American Civil War started in 1861 and ended in 1865.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cc8e4bd711be7fc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Slavery was abolished in America in the which year?', '{"A":"1861","B":"1865","C":"1808","D":"1898"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States criminalized the international slave trade in 1808.Slavery was made unconstitutional in 1865, following the American Civil War.It lasted from 1861 to 1865.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8c3a51effaf43166', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In June 1948, under Soviet Union influence, Germany built a wall between East and West Germany?', '{"A":"To divide Berlin into two parts","B":"To stop their citizens from escaping to the west","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In June 1948, the Soviet Union, under the leadership of Joseph Stalin, blocked the Western Allies'' access to Berlin.It was deep within the Soviet-occupied zone of Germany.In response, the Western Allies organized the Berlin Airlift to supply the city.However, it was in 1961, under the leadership of Nikita Khrushchev, that the Soviet Union built the Berlin Wall to:Divide Berlin into two parts (East Berlin and West Berlin)Stop East German citizens from escaping to the West', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a9d7f93ace1361be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In the early period which endemic is called black death?', '{"A":"Sars","B":"Liporasy","C":"Plague","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the early period, the endemic known as the "Black Death" is the plague.The plague is a pandemic disease that devastated Europe in the 14th century, killing an estimated 75 to 200 million people, approximately 30-60% of Europe''s population.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9100688d03cc86a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When Switzerland got the status of neutral state?', '{"A":"1800","B":"1810","C":"1815","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Switzerland gained the status of a neutral state in 1815, at the Congress of Vienna, which was held after the Napoleonic Wars.The Congress of Vienna recognized Switzerland''s independence and sovereignty, and established its permanent neutrality.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e7796a0fbb60a919', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which famous personality of English literature awarded nobel Prize in 1907?', '{"A":"Paul Haysay","B":"Rudyard Kipling","C":"Ramain Ronnaland","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1907, Rudyard Kipling was awarded the Nobel Prize in Literature, as the first English-language writer to receive the prize, and at 41, its youngest recipient to date.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fe4e3c8bb4b6fd51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In 2019-20 Australian Bush Fire Season is names as _____?', '{"A":"Dark summer","B":"White summer","C":"Black summer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 2019–20 Australian bushfire season is named as Black SummerThe fires reached their peak during the summer months, from December 2019 to February 2020.The extent of Damage: By early 2020, the bushfires had ravaged vast areas of Australia, burning an estimated 18 million hectares (44.5 million acres), destroying over 3,000 homes, and killing at least 33 people.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bc52ff677543ecb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Sun Yat Sen park and casa garden is in which city of China?', '{"A":"Washington","B":"Macau","C":"Shanghai","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sun Yat Sen Park is a city park in Macau China.The park is named after Dr. Sun Yat Sen, the Republic of China’s founding father.It is the largest park on the Macau.The park, first opened in 1987.It was initially named ‘Canal Dos Patos Park’ to honour China and Portugal’s friendship.Casa Garden was once the home of wealthy Portuguese trader Manuel Pereira, who built this park around 1770. It was officially designated as a UNESCO World Heritage Site in 2005.', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ec130eeea6bb4f6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Israel occupied East Jerusalem in _____?', '{"A":"1967","B":"1969","C":"1979","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Israel captured the West Bank and East Jerusalem in the 1967 Middle East war. The vision for an independent Palestinian state generally includes the West Bank and Gaza, with East Jerusalem as its capital.******RY 15-01-2023', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_94dff7ffee64e6ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Where is tower bridge located?', '{"A":"London","B":"Peris","C":"Glasgow","D":"Liverpool"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tower Bridge is a Grade, built between 1886 and 1894, designed by Horace Jones and engineered by John Wolfe Barry. The bridge crosses the River Thames close to the Tower of London.It is one of five London bridges owned and maintained by the Bridge House Estates, a charitable trust founded in 1282.', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7b0847adeac2cad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is a basin?', '{"A":"Deep area of River","B":"Lower area of land","C":"High area of land","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A basin is a depression, or dip, in the Earth''s surface.River Drainage Basins.A river basin is made up of many different watersheds.', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_07d45197520a3d52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Iraq invaded Kuwait on ________?', '{"A":"August 2, 1990","B":"July 2, 1991","C":"June 2, 1990","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Iraqi invasion of Kuwait was an operation conducted by Iraq on 2 August 1990Persian Gulf War, also called the Gulf War, (1990–91), international conflict that was triggered by Iraq’s invasion of Kuwait Iraq Kuwait Commanders and leaders Saddam Hussein Jaber III Strength88,00016,000 (Army)2,200 (Air Force)1,800 (Navy) Casualties and losses295 killed361 wounded(Unconfirmed Kuwaiti claims)420 killed12,000 captured', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a9498d246e6dbda9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Currently, about how much world’s goods trade (by volume) is carried on ships?', '{"A":"80%","B":"20%","C":"60%","D":"None of thes"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Currently, about 80% of the world’s goods trade by volume is carried on ships.Maritime transport is crucial, handling over 70% of global trade by value.', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
