INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_934b46260de198c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following uses source of light?', '{"A":"Perspective","B":"Conventional","C":"Non-perspective","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Perspective uses a light source to create depth and dimension in visual representations.This making objects appear more realistic by showing them in three-dimensional space.', 0, 0, 0, 1790965667471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6ae8313f28014440', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Yemen Crisis started in _______?', '{"A":"2009","B":"2011","C":"2013","D":"2015"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Yemeni Crisis began in 2011–2012The Yemeni Crisis revolution against President Abdullah Saleh, who had led Yemen for 33 years.Yemen''s political crisis began in 2011, amid the Arab Spring and the ongoing Houthi insurgency.ND-7-5-2023', 0, 0, 0, 1790965667558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a0c0fbdf8b108b60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the most populated city in Pakistan?', '{"A":"Islamabad","B":"Lahore","C":"Karachi","D":"Murree"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karachi, the most populous city in Pakistan and its financial hub.Karachi is the former capital of Pakistan.It is the capital of Sindh province.It has seven districts:Karachi Central,Karachi East,Karachi South,Karachi West,Korangi,Malir,Keamari.It is located at the southern tip of the country.Additional information:List of top 5 populated city of PakistanCity2024 PopulationKarachi11,624,219Lahore6,310,888Faisalabad2,506,595Rawalpindi1,743,101Multan1,437,230', 0, 0, 0, 1790965667558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7c975e03be57273f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Caracas is a famous city of _____?', '{"A":"Venezuela","B":"Sudan","C":"Italy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caracas is the capital and largest city of Venezuela, a country located in South America.It is a significant cultural, economic, and political center in the region.', 0, 0, 0, 1790965667558) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b24da277391a1384', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The political party of Mussolini?', '{"A":"People Republic","B":"National Socialist Party","C":"Fascist Party","D":"None of these."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Benito Mussolini was an Italian politician and leader of the National Fascist Party.He ruled Italy as Prime Minister from 1922 until his ousting in 1943.He is known for his authoritarian and fascist regime, which allied with Nazi Germany and Japan during World War II.Mussolini was born in Predappio, Italy in 1883.He was executed in Milan, Italy in 1945.', 0, 0, 0, 1790965667558) ON CONFLICT(id) DO NOTHING;
