INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_945bd7a94f058a72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'West Indies consists of how many islands?', '{"A":"1000","B":"1100","C":"1200","D":"1400"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation West Indies, Spanish Indias Occidentales, French Indes Occidentales, Dutch West-Indië, crescent-fashioned group of islands more than 2,000 miles (3,two hundred km) long keeping apart the Gulf of Mexico and the Caribbean Sea, to the west and south, from the Atlantic Ocean, to the east and north. From the peninsula of Florida at the mainland of the us, the islands stretch 1,200 miles (1,900 km) southeastward, then 500 miles (800 km) south, then west along the north coast of Venezuela on the South American mainland.', 0, 0, 0, 1790965671609) ON CONFLICT(id) DO NOTHING;
