INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d2603e9639d34e31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which one of the following city is also known as the City of Canals?', '{"A":"Brazil","B":"Venice","C":"Singapore","D":"Korea"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ​Venice is world-famous for its canalsit is built on an archipelago of 118 islands formed by about 150 canals in a shallow lagoonVenice, the capital of northern Italy’s Veneto regionVenice has no roads, just canalsVenice and its lagoon are one of the most unique cities in the world.The city was historically the capital of the Republic of Venice for over a millennium, from 697 to 1797ND11-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_68ba1e438d4ef643', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the currency of North Korea?', '{"A":"North Korean Won","B":"Franc","C":"Loti","D":"Togrog"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation North Korea Capital is Pyongyang.North Korea Currency is the North Korean Won.North Korea official language is Korean.North Korea located is in Continent Asia.North Korea Primary Religion is Secular.North Korea Head of Govt. is Prime Minister– Sir Abubakar Tafawa Balewa.North Korea Parliament called .Tricks for RememberWONMindTrick: Korea’s Won in the Battle1)South Korea2)North Korea RK6-12-2022****nd9-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9e2b2af372dcceba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Population is a group of:', '{"A":"Individuals in a species","B":"Species in a community","C":"Individuals in a family","D":"communities in an ecosystem","E":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A group of organisms of one species occupying a defined area is termed a population. In nature, we rarely find isolated, single individuals of any species.The total number of people living in an area, city, country, or the world at a specific time is called Population. ***ND1-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_097c437bc368367c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Anything that can be used to earn a living is called:', '{"A":"Outcome","B":"Reservoir","C":"Resource","D":"None of these","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Resource means وسیلہ، ذریعہA resource is a physical material that humans need and value such as land, air, and water. Resources are characterized as renewable or nonrenewable; a renewable: resource can replenish itself at the rate it is used, while a nonrenewable: resource has a limited supply.***ND1-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
