INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bdc8f0dab52acbfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the global recommendation for the period for breast-feeding of baby?', '{"A":"At least one year","B":"Two years or longer","C":"As long as possible","D":"Until the mother milk dries up","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation breastfeeding is important for the baby because Breastfed babies are healthierthe World Health Organization also recommends exclusive breastfeeding for about the first 6 months for up to 2 years of age or longer.World Breastfeeding Week first observed in 1991.World breastfeeding week: 1st to the 7th of August annually Theme 2022: Step Up for Breastfeeding: Educate and Support***ND1-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d330b3b01f5a2b71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Why is breastfeeding important for the baby?', '{"A":"I do not believe it is different from formula feeding","B":"Formula feeding allows the father of baby to be more involved","C":"Breastfed babies are healthier","D":"Breastfed babies remain closer to their mothers throughout their lives"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation breastfeeding is important for the baby because Breastfed babies are healthierIt protects against allergies, sickness, and obesity. It protects against diseases, like diabetes and cancer. the World Health Organization also recommends exclusive breastfeeding for about the first 6 months for up to 2 years of age or longer.World Breastfeeding Week first observed in 1991.World breastfeeding week: 1st to the 7th of August annually Theme 2022: Step Up for Breastfeeding: Educate and Support***ND1-2-2023', 0, 0, 0, 1790965671750) ON CONFLICT(id) DO NOTHING;
