INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3c95c80d6bc87095', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The season changes because of the ____________?', '{"A":"Moon is revolving round the earth","B":"Earth is revolving round its axis","C":"Earth is revolving around the sun","D":"Planet Mars is attracting the sun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation موسم بدلتا ہے کیونکہ زمین سورج کے گرد گھوم رہی ہے۔Earth''s tilted axis causes the seasons. Throughout the year, different parts of Earth receive the Sun''s most direct rays. So, when the North Pole tilts toward the Sun, it''s summer in the Northern Hemisphere. And when the South Pole tilts toward the Sun, it''s winter in the Northern Hemisphere.', 0, 0, 0, 1790965672522) ON CONFLICT(id) DO NOTHING;
