INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0b06012ca2c3b84f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The lower house of US Congress is called?', '{"A":"Diet","B":"The senate","C":"House of Representatives","D":"House of commons"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:CCongress is made up of two houses, just how most state legislatures are made up. The upper house is called the Senate, and the lower house is called the House of Representatives.', 0, 0, 0, 1790965672888) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_050bd20a0a1e1674', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The rainiest place in the world is ___________?', '{"A":"Beijing, China","B":"Riyadh, Saudi","C":"Quetta, Pakistan","D":"Mawsynram, India","E":"Kabul, Afghanistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mawsynram of India, is the wettest place in the world. It receives an annual rainfall of 11,871 millimetres.The mountainous terrain of the surrounding land forces the northward-moving warm moist monsoon winds coming from the Bay of Bengal to converge over Mawsynram.', 0, 0, 0, 1790965672888) ON CONFLICT(id) DO NOTHING;
