INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2080a0ebd5785432', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which 19th-century British painter and sculptor painted "Monarch of Glen"', '{"A":"Leonardo da Vinc","B":"Edwain Landseer","C":"Madagascar","D":"Galapagos islands"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:This is a reproduction of the 1851 painting by Edwin Landseer, entitled Monarch of the Glen. It is a wonderful image.', 0, 0, 0, 1790965672888) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c7ec9a1bd6be9496', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What do understand by "Ex officio"?', '{"A":"By one''s office","B":"Retired officer","C":"Terminated officer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:The term "Ex-officio" is a common Latin expression for "absent." It should not be used to describe the type of membership of an organization, but to explain the obligations or privileges that an individual has based on his or her position as a member of the board or committee.', 0, 0, 0, 1790965672888) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b630a5b6d13ef2fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'On which day of November of the leap year the US Presidential elections are held?', '{"A":"First Monday","B":"First Tuseday","C":"First Thirsday","D":"First Sunday"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the United States, Election Day is the annual day set by law for the general elections of federal public officials. It is statutorily set by the Federal Government as "the Tuesday next after the first Monday in the month of November" Equaling the Tuesday occurring within November 2 to November 8.', 0, 0, 0, 1790965672888) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3b8b3227d95b2521', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which is the Odd word among these ?', '{"A":"Motorcar","B":"Boat","C":"Aeroplane","D":"Airport"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three of the following four words are alike in a certain way and one is different. so airport is different', 0, 0, 0, 1790965672971) ON CONFLICT(id) DO NOTHING;
