INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_826f1ff42cbe671d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following discipline is the Nobel Prize awarded ?', '{"A":"Physics and Chemistry","B":"Psychology or medicine","C":"Lecture peace and economics","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Since 1901, the Nobel Prize has been awarded in the fields .1 physics2 chemistry3 physiology 4 medicine5 literature 6 peace while a memorial prize in economic sciences was added in 1968.', 0, 0, 0, 1790965672971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2157e3338fbcf679', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which organization takes Human rights Initiative?', '{"A":"Common wealth","B":"IMF","C":"UNO","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Commonwealth Human Rights Initiative (CHRI) non-governmental organisation which works towards the practical realization of human rights in the countries of the Common wealthFormation 1987Headquarters New Delhi, India', 0, 0, 0, 1790965672971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_151cb8cc1330434a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is bootlegging?', '{"A":"Form of smuggling","B":"Form of drug","C":"Form of Indian religion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bootlegging refers to the illegal transportation, production, or sale of goods, especially alcohol during Prohibition in the U.S. It is a form of smuggling as it involves moving illegal goods secretly.', 0, 0, 0, 1790965672971) ON CONFLICT(id) DO NOTHING;
