INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_dbfce0543043e1a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country has the Largest Muslim country by population in the world?', '{"A":"Malysia","B":"Pakistan","C":"Turkey","D":"Indonesia"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslim Population by Country 2026Indonesia. 242,700,000Pakistan. 240,760,000India. 200,000,000Bangladesh. 150,800,000Nigeria. 97,000,000.Additional information:The largest country by population in the world is India.The largest Muslim city by population is Jakarta.Last updated by NA on 16-07-2026', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b82ebd96bf1f1b7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Great Pyramids of Giza, the oldest of the seven wonders of the world, located in _____?', '{"A":"Egypt","B":"Jordan","C":"Saudi Arabia","D":"Iraq"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pyramid of Giza is located in Egypt.It is one of the 7 wonders of the ancient world.These ancient structures are situated on the Giza Plateau, near Cairo.The houses surrounding the pyramid were made of clay bricks dried in the sun.All the houses had flat roofs.Last verified on 30-09-2026', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_63423dd8a7f34f3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which one of the following is the capital of Brazil?', '{"A":"Harare","B":"Ottowa","C":"Tokyo","D":"Brasilia"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brazil Capital is Brasilia.Brazil Currency is Real.Brazil official language is Portuguese.Brazil located is in Continent South America.Brazil Primary Religion is Christianity.Brazil national game is Football. Brazil Parliament called National Congress.Last verified on 07-02-2026', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9a7ed4e81e0bf2e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Largest Continent (by Area and Population) of the World is _______?', '{"A":"Asia","B":"Europe","C":"Africa","D":"North America"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asia is the largest continent by land area and population.It covers about 44.58 million sq km.Around 60% of the world’s population lives in Asia.It has 40+ countries, including China, India, and Indonesia.It makes up about 30% of Earth’s land area.Additional information:Australia is the smallest continent in the world by area.Antarctica is the smallest continent in the world by population.Last verified on 07-02-2026', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_63d824474b3f0b87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is known as the "Dark Continent" because of its unexplored characteristic for a fairly long period of time as?', '{"A":"Asia","B":"Africa","C":"Europe","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Africa is known as the "Dark Continent"Because much of its land remained unexplored by Europeans for a long time.The world''s second-largest and second-most populous continent after AsiaAdditional information:First largest continent by area: Asia,Second largest continent by area: Africa,Third largest continent by area: North America,Fourth largest continent by area: South America,Fifth Largest Continent by area: Antarctica,Sixth Largest Continent by area: Europe,Smallest continent by area: Australia.Last updated: 20-09-2026 by NA', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c404a1be520fdc32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called Playground of Europe?', '{"A":"Turkey","B":"France","C":"Switzerland","D":"Spain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Switzerland is known as the playground of Europe.This nickname highlights its diverse landscapes, from high peaks to pristine lakesAdditional information The capital is Bern.The currency is the Swiss Franc.official language is German; French; Italian.Continent Europe.Religion is Christianity.Parliament called Bundesversammlung.Last updated: 20-09-2026 by NA', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f549b9a0901ff27a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which Continent has no desert?', '{"A":"Europe","B":"Australia","C":"N.America","D":"S.America"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Europe is the only continent without a desert.It has a temperate climate with sufficient rainfall.Additional information:Divided by the Ural MountainsSecond-smallest continentCovers 2% of Earth’s surfaceArea: 10.18 million km²Last verified on 16-01-2026', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2d41514a7a3522c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the capital of Pakistan?', '{"A":"Lahore","B":"Islamabad","C":"Karachi","D":"Sialkot"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capital: IslamabadConstruction began: 1960Officially became the capital: 14 August 1967President at the time: Ayub KhanPrevious capital: KarachiAdditional informationCurrency is the Pakistani Rupee.Official language is Urdu; English.Located in Continent Asia.Primary Religion is Islam.Head of Govt. is Prime Minister –Shehbaz Sharif.Pakistan Parliament is called the National Assembly & Senate.Tricks for RememberRUPEEMind Tricks : PICS of MN***PICS***P - PakistanI - IndiaC - CeylonS - Srilanka**MN**M - MaritiusN - Nepal', 0, 0, 0, 1790965673180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8f3771334dc8c222', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The ''Statue of Liberty'' was a gift to the United States on the occasion of its independence. Which country gifted it?', '{"A":"Germany","B":"UK","C":"France","D":"Japan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The Statue of Liberty" was a gift from France to the USA.It dedicated on October 28, 1886.It recognized as a universal symbol of freedom.It is located in New York.It has a height of 93 meters.The construction started in 1876.The construction was completed in 1886.It is designed by French sculptor Frederic Auguste Bartholdi.It was designated on October 15, 1924.Last Updated by NA on 13-01-2026', 0, 0, 0, 1790965673267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b435ba918366d4e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called the Cockpit of Europe?', '{"A":"Italy","B":"France","C":"Belgium","D":"Germany"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Belgium is known as the “Cockpit of Europe.”The nickname refers to the many major European battles fought on Belgian territory.Belgium is located in Western Europe.Additional information:Capital: BrusselsCurrency: Euro (€)Official languages: Dutch, French, and GermanLast verified on 28-09-2026', 0, 0, 0, 1790965673267) ON CONFLICT(id) DO NOTHING;
