INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9d4fa7e89eb62b14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Al Jazeera TV channel belongs to which country?', '{"A":"Pakistan","B":"Iran","C":"Syria","D":"Qatar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al Jazeera is a Qatar-based international news network headquartered in Doha, Qatar.It was launched in 1996 as an Arabic-language news channel.Al Jazeera English was launched in 2006 as a 24-hour English-language news channel.The network is partially funded by the government of Qatar.Al Jazeera operates under the Al Jazeera Media Network.Last verified on 09-08-2026', 0, 0, 0, 1790965673928) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8b6e5707af5cf94e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following countries hosted the 2026 Winter Olympics?', '{"A":"Japan","B":"France","C":"China","D":"Italy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 2026 Winter Olympics were hosted by Italy.The games were held in Milan and Cortina d’Ampezzo from 6–22 February 2026.Italy became the host country for the third Winter Olympics in its history.Additional information:Winter Olympics 2022: ChinaSummer Olympics 2024: FranceSummer Olympics 2028: United StatesSummer Olympics 2020: JapanLast verified on 10-05-2026', 0, 0, 0, 1790965673928) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_059b82bcb4e17795', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Suez Canal is connects / between / links ______?', '{"A":"Arabian Sea and Red Sea","B":"Red Sea and North Sea","C":"Mediterranean Sea and North Sea","D":"Mediterranean Sea and Red Sea"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Connection: Links Mediterranean Sea to Red SeaLocation: EgyptOpened: 1869Length: 193 kmPurpose: Provides the shortest maritime route from Europe to AsiaLast verified on 08-02-2026', 0, 0, 0, 1790965673928) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_69190061cda1ec8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The driest and windiest continent in the world is?', '{"A":"Antarctica","B":"Australia","C":"Africa","D":"South America"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antarctica is the driest and windiest continent in the world.It has extremely low rainfall.It is known as a polar desert.Strong katabatic winds make it the windiest continent.It is also the coldest continent on Earth.It is located around the South Pole.Last verified on 20-06-2026', 0, 0, 0, 1790965673928) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_982d7b250994f8f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Fidel Castro was the President of which country?', '{"A":"Cuba","B":"Spain","C":"France","D":"Canada"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fidel Castro was the leader of Cuba.He led the Cuban Revolution and came to power in 1959.He served as Prime Minister of Cuba (1959–1976) and then as President (1976–2008).He born on 13 August 1926.He died on 25 November 2016 (aged 90).Last verified on 08-08-2026', 0, 0, 0, 1790965673928) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4b1b4d490651d4f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Mount Logan is the highest mountain located in which country?', '{"A":"United States","B":"Canada","C":"Russia","D":"New Zealand"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mount Logan is the highest mountain in Canada.It is located in the Yukon territory of Canada.It is the second-highest peak in North America after Denali.It was named after William Edmond Logan.Its highest point is 5,959 meters (19,551 feet) above sea level.First ascent: 1925Last verified on 22-06-2026', 0, 0, 0, 1790965674017) ON CONFLICT(id) DO NOTHING;
