INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_44d7a7043a65c7d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The biggest/largest Islamic country by area is _____?', '{"A":"Sudan","B":"Libya","C":"Kazakhstan","D":"Egypt"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Muslim country by area is Kazakhstan.Largest Muslim country by Population is Indonesia.Additional information:World Largest country by area is Russia.World Largest Country by Population is India.Last verified on 27-07-2026', 0, 0, 0, 1790965674017) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ccddefaf5c8dc1e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Bondi beach in which country?', '{"A":"Canada","B":"USA","C":"UK","D":"Australia"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Sydney, New South Wales, AustraliaDistance from Sydney CBD: 7 km (4 miles)State: New South WalesCoast: Pacific Ocean (Tasman Sea)Established as a Public Beach: 1882Last verified on 26-07-2026', 0, 0, 0, 1790965674017) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5f5a5a0acd2057f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Capital of Syria is?', '{"A":"Baghdad","B":"Damascus","C":"Beirut","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syria Capital is Damascus.Syria Currency is Syrian Pound.Syria official language is Arabic.Syria located is in Continent Asia.Syria Primary Religion is Islam, Christianity.Tricks for RememberPOUND S-E-S-UMind Trick : Sheshu(a name) plays in the Pond.**S-E-S-U**S - South SudanE - EgyptS - SyriaU - UKLast verified on 26-07-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5cfbada3ec1bfa4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called Land of Kangaroo?', '{"A":"England","B":"New Zealand","C":"Australia","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Australia is called the "Land of Kangaroo."The kangaroo is the national animal of Australia.Kangaroos are found naturally only in Australia.They are one of the country''s most famous wildlife symbols.Australia is known for its unique plants and animals.Last verified on 13-07-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5fabb485eb307153', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country has the longest coastline in the world?', '{"A":"Newzeland","B":"Canada","C":"Indonesia","D":"Russia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Canada has the longest coastline in the world, measuring about 243,042 km.It borders the Atlantic, Pacific, and Arctic Oceans.Additional information:Norway (100,915 km)Indonesia (54,716 km)Russia (37,653 km)United States (19,924 km)China (14,500 km)West Bengal has the smallest coastline.The new length of the coastline of Pakistan is 1058 km.Last verified on 22-07-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_96f6577cfe312cc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the Capital of Greece?', '{"A":"Budapest","B":"Dublin","C":"Athens","D":"Tarawa Atoll"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greece Capital is Athens.Greece Currency is Euro.Greece official language is Greek.Greece located is in Continent Europe.Greece is famous for its Olive trees.Greece Primary Religion is (Christianity) Orthodoxy.Greece Parliament called Chamber Of Deputies.Tricks for RememberEURO BIG -FAN-PI –SMSMind Trick : BIG FAN of PI and wished through SMS**BIG**B-BelgiumI-IrelandG-Germany**FAN**F-FranceA-AustriaN-Netherland**PI**P-PortugalI-Italy**SMS**S-SpainM-MaltaS-SolvariaVerified & Updated', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ac4fcfd7526fda61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The largest wheat producing country in the world is _______?', '{"A":"USA","B":"India","C":"Pakistan","D":"China"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China is the largest wheat producer in the world.USA is among the largest wheat exporters globally due to strong agricultural infrastructure.Additional information:China: ~135–140 million metric tonsIndia: ~110–117 million metric tonsRussia: ~80–90 million metric tonsUnited States: ~45–55 million metric tonsEuropean Union: ~130–142 million metric tons (combined)Last verified on 21-04-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_dc13249fdb45b8c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'On the flag of which country is there an image of Maple Leaf?', '{"A":"New Zealand","B":"Brazil","C":"Thailand","D":"Canada"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Maple Leaf is the national symbol of Canada.Canada''s present national flag was officially adopted on 15 February 1965.The flag features a red maple leaf with 11 points between two red vertical bands.15 February is celebrated every year as National Flag of Canada Day.Additional information:Capital: OttawaCurrency: Canadian Dollar (CAD)Official Languages: English and FrenchNational Animal: BeaverNational Sport: Ice Hockey (winter) and Lacrosse (summer)Last verified on 21-07-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b47824d7f7d39ac3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Democracy works better in countries with?', '{"A":"High literacy rate","B":"Low literacy rate","C":"No education system","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Democracy works more effectively where people are educated and aware of their rights and responsibilities.Literate citizens can make informed decisions while voting.Education promotes political awareness, tolerance, and active public participation.A high literacy rate strengthens democratic institutions and good governance.Last verified on 21-07-2026', 0, 0, 0, 1790965674096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b77539b4aee84f1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of following is the smallest ocean of the world?', '{"A":"Pacific","B":"Indian","C":"Atlantic","D":"Arctic"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arctic is the shortest ocean in the world.Additional information:The Pacific is the largest ocean in the world.71% of Earth''s surface is covered by ocean.The warmest ocean in the world is the Indian ocean.The hottest ocean area is the Persian Gulf.Diamantina Trench is the deepest place in the Indian ocean.Country Jordon has no ocean.The five major oceans listed by size from largest to smallest are the:The Pacific OceanThe Atlantic OceanThe Indian OceanThe Southern OceanThe Arctic OceanLast verified on 07-06-2026', 0, 0, 0, 1790965674097) ON CONFLICT(id) DO NOTHING;
