INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2ff6527001ef22cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Arabian Desert is primarily located in which region?', '{"A":"Northern Africa","B":"Western Asia","C":"Southern Europe","D":"Central America"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arabian Desert is located in Western Asia.It is one of the largest deserts in the world.It primarily covers much of the Arabian Peninsula, including countries such as:Saudi Arabia (largest portion)YemenOmanUnited Arab EmiratesQatarKuwaitJordanIraqLast verified on 06-07-2026', 0, 0, 0, 1790965674559) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_33ddf12c5b28752e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country parliament has the largest membership?', '{"A":"Canada","B":"Russia","C":"China","D":"India"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China''s National People''s Congress (NPC) is the largest parliamentary body in the world.It has more than 3,000 members.The NPC is China''s highest organ of state power.It meets annually in Beijing.Additional information:The parliament with the smallest membership is the Congress of the Federated States of Micronesia.It has just 14 members.Last verified on 06-07-2026', 0, 0, 0, 1790965674559) ON CONFLICT(id) DO NOTHING;
