INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f578aad2da4f7df9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'How many member countries are there in BRICS grouping?', '{"A":"Eight","B":"Eleven","C":"Five","D":"Seven"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BRICS has 11 full member countries after the inclusion of Indonesia in 2025.BrazilRussiaIndiaChinaSouth AfricaEgyptEthiopiaIranSaudi ArabiaUnited Arab Emirates (UAE)IndonesiaAdditional information:BRICS is a grouping of major emerging economies for economic and political cooperation.Founded: 2006 (first BRIC grouping)Headquarters: Shanghai, China (New Development Bank)First Summit Host: Russia (2009)South Africa joined: 2010Last verified on 24-06-2026', 0, 0, 0, 1790965674806) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0fc5646aa3b3b28f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Kyoto is located in which country?', '{"A":"China","B":"South Korea","C":"Japan","D":"Thailand"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kyoto is a historic city in Japan known for its rich culture and heritage.It served as the capital of Japan until 1868.The city was originally founded in 794 AD as Heian-kyō.Today, it is famous for temples, shrines, and traditional Japanese culture.Last verified on 23-06-2026', 0, 0, 0, 1790965674806) ON CONFLICT(id) DO NOTHING;
