INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8d5467a35bc5eacf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Tahrir Square is situated in _____?', '{"A":"Cairo","B":"Istanbol","C":"Kabul","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tahrir Square is located in Cairo, Egypt.It is also known as “Liberation Square” (Martyr Square).Formerly, it was called Ismailia Square.It has been a major center of political protests and revolutions.Established: 1867Famous Events: 1919 & 2011 revolutionsLast verified on 31-03-2026', 0, 0, 0, 1790965675456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d2fb20935f2e5930', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Al Taksim square is located in?', '{"A":"America","B":"Istanbul","C":"Spain","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taksim Square is located in Istanbul, Turkey.It is considered the heart of modern Istanbul.It is inaugurated in 1928.The 280-year-old Taksim Square can be a tourist attraction.Last verified on 30-03-2026', 0, 0, 0, 1790965675456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bfc2af85a1e7513e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the oldest mountain in the 400 million years group?', '{"A":"Himalayas","B":"Alps","C":"Appalachian Mountains","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Appalachian Mountains in North America formed around 400 million years ago, making them one of the oldest mountain ranges in the world.Their eroded and rounded peaks show their great age compared to younger, sharper mountains like the Himalayas.Last verified on 30-03-2026', 0, 0, 0, 1790965675554) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_22ca5aeb7de7c229', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The world''s largest Glacier is _____?', '{"A":"Lambert","B":"Siachen","C":"Hispad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lambert-Fisher glacier is considered the largest glacier in the world, located in Antarctica.It is approximately 400 miles (640 km) long and 60 miles (97 km) wide.It covering an area of about 100,000 square miles (260,000 square km).Last verified on 30-03-2026', 0, 0, 0, 1790965675554) ON CONFLICT(id) DO NOTHING;
