INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f16da8fa5b22ba75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the Capital of Lebanon country?', '{"A":"Beriut","B":"Cairo","C":"Bako","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lebanon Capital is Beirut.Lebanon Currency is Lebanese Pound.Lebanon official language is Arabic; French.Lebanon located is in Continent Asia.Lebanon Primary Religion is Islam, Christianity.Lebanon Head of Govt. is Prime Minister –Najib Mikati.Lebanon Parliament called .Tricks for RememberPOUND S-E-S-UMind Trick : Sheshu(a name) plays in the Pond.**S-E-S-U**S - South SudanE - EgyptS - SyriaU - UK Last verified on 14-03-2026', 0, 0, 0, 1790965675554) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_86124fa39db6d89c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Continent Antarctica lies at the?', '{"A":"North Pole","B":"South North Pole","C":"South Pole","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antarctica is the southernmost continent on Earth.It is centered around the South Pole.It is covered with ice.It is the coldest continent.No permanent human settlements, only research stations.Additional information:Area: About 14 million km²Ice coverage: ~98% of the continentInteresting fact: Holds around 90% of the world’s iceWildlife: Penguins, seals, and migratory birdsLast verified on 14-03-2026', 0, 0, 0, 1790965675555) ON CONFLICT(id) DO NOTHING;
