INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_646582e743800690', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', '10 Downing Street is the official residence of the Prime Minister of which country?', '{"A":"French Prime Minister","B":"USA Prime Minister","C":"British Prime Minister","D":"Queen of England"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 10 Downing Street, colloquially known as Number 10.It is the official residence and office of the British Prime Minister.It located on Downing Street in London''s City of Westminster.Additional information:It was constructed between 1682 and 1684 by architect Kenton Couse.The building, over 300 years old, boasts approximately 100 rooms.It was officially designated on 14 January 1970.Last verified on 02-02-2026', 0, 0, 0, 1790965675788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c3628da1821c9605', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Red sea is between _________?', '{"A":"Arabia and Qatar","B":"Arabia and Africa","C":"Arabia and Asia","D":"Germany and Scandinavia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red Sea Location: Between Arabian Peninsula (Asia) and Northeastern AfricaType: Sea (arm of the Indian Ocean)Connection to Ocean: Via Bab-el-Mandeb StraitDistinct Feature: Unlike the Caspian or Aral Seas, it has direct connection to the oceanLength: ~2,300 km longBorders: Egypt, Sudan, Eritrea (Africa) and Saudi Arabia, Yemen (Asia)Last verified on 10-02-2026', 0, 0, 0, 1790965675788) ON CONFLICT(id) DO NOTHING;
