INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3b85e977cb3869c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the second largest desert in the world after the Sahara desert?', '{"A":"Kalahari Desert","B":"Arabian Desert","C":"Gobi Desert","D":"Libyan Desert"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arabian Desert is the second-largest desert in the world after the Sahara.It spans much of the Arabian Peninsula.Additional information:Area: ~2,330,000 km²Location: Covers Saudi Arabia, Oman, UAE, Yemen, Jordan, Iraq, Kuwait, QatarOther Large Deserts:1. Sahara – 9,200,000 km²3. Gobi – 1,295,000 km²4. Kalahari – 900,000 km²Last verified on 15-01-2026', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_710ab6119cc0fe0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Dome of rock is located in?', '{"A":"Lebanon","B":"Jerusalem","C":"Sria","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dome of the RockLocation: Temple Mount, Old City of JerusalemCompleted: 691–692 CE by Umayyad Caliph Abd al-MalikBuilt on: Site of the Second Jewish TempleHistorical Fact: Original temple destroyed in 70 CE by RomansSignificance: Important Islamic shrine and landmarkLast verified on 15-01-2026', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3e97a5ce02ae8c0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Greenwich is located near which country?', '{"A":"London","B":"Switzerland","C":"Belgium","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenwich is an area in south-east London, located in EnglandIt lies on the south bank of the River Thames in the historic county of Kent.It is famous for the Prime Meridian (0° longitude).It is used as the reference for Greenwich Mean Time (GMT).The Greenwich meridian, also known as the prime meridian, passes through the following countries:EnglandFranceSpainAlgeriaMaliBurkina FasoTogoGhana Antarctica', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4bbf0a77213a5cda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Nile River Flows in ______?', '{"A":"Asia","B":"Africa","C":"Europe","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nile River flows through Northeast AfricaIt begins in the rivers that flow into Lake Victoria It is the longest river in Africa and the world.It is the primary source of water for EgyptEgypt is known as the "Gift of Nile"The Nile has two major tributaries:The White NileThe Blue Nile (begins at Lake Tana in Ethiopia)', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
