INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ba6c9484172c53af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Spratly Islands in the South China Sea are disputed between China and ______?', '{"A":"Vietnam","B":"Malaysia","C":"Philippines","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Spratly Islands in the South China Sea are a disputed territory, claimed by several countries, including:ChinaVietnamMalaysiaPhilippinesMost of the "maritime features" in this area have at least six namesIn 1968, oil was discovered in the region.On 11 March 1976, the first major Philippine oil discovery occurred off the coast of Palawan, near the Spratly Islands territory.', 0, 0, 0, 1790965676250) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_95993f503c123428', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the largest river in Asia?', '{"A":"Indus","B":"Yangtze","C":"Ganges","D":"Mekong"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Yangtze River is the longest river in Asia.It is the third longest in the world.It is length over 6,300 kilometers (4,000 miles) long.It is originates in the highlands of Tibet.It is flows into the East China Sea at Shanghai, the world''s busiest port.It is considered the heart of China.Additional information:Yellow River: The second longest river in Asia.It is located in ChinaMekong: A river that flows through China, Myanmar, Laos, Thailand, Cambodia, and Vietnam', 0, 0, 0, 1790965676250) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8563c26fcdc26c97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'In which country paper was first invented?', '{"A":"USA","B":"China","C":"Japan","D":"India"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paper was first made in Lei-Yang, China by Tsai Lun, a Chinese court official.The earliest known use of paper money in China dates back to the Tang dynasty.Tang dynasty lasted from the year 618 to 907 AD.', 0, 0, 0, 1790965676250) ON CONFLICT(id) DO NOTHING;
