INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5b590b5411ce6be1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Lake Baikal is situated in the which country?', '{"A":"Russia","B":"Denmark","C":"USA","D":"Canada"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lake Baikal is situated in southern Siberia, Russia, It is a rift lake and the deepest lake in the world It has a length of 397 miles (640 km).It has a maximum width of 49 miles.', 0, 0, 0, 1790965678909) ON CONFLICT(id) DO NOTHING;
