INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3172f74f0ec1c658', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The largest natural gas producer country in the world is ____?', '{"A":"India","B":"US","C":"Russia","D":"Both B and C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The US is the largest producer of natural gas in the world.It accounting for 32% of global primary energy consumption.Russia is the second-largest producer.The top 10 natural gas producers account for about 73% of total global production:1. United States 2. Russia 3. Iran 4. China 5. Qatar 6. Canada 7. Australia 8. Saudi Arabia 9. Norway 10. Algeria', 0, 0, 0, 1790965679018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_24f2e80367ca8bd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which continent has minimum birth rate in the world?', '{"A":"Asia","B":"Africa","C":"Australia","D":"Europe"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Europe has the lowest fertility rate of the continents.Averaging around 1.5 births per woman. Less than 5% of all global birthsList of lowest to highest Second: North America. Average TFR: ~1.6 births per womanThird: Asia, Average TFR: ~1.9 births per womanFourth: Latin America and the Caribbean. Average TFR: ~2.0 births per womanFifth: Oceania. Average TFR: ~2.1 births per womanAfrica has the highest fertility rate of the continents.Africa: 4.7 children per womanLast updated by NA on 16-07-2026', 0, 0, 0, 1790965679018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e2e46628c808affb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is known as Birds continent?', '{"A":"North America","B":"South America","C":"Asia","D":"Europe","E":"Australia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation South America is referred to as the Bird continent.Because it is inhabited by a large number of birds.', 0, 0, 0, 1790965679018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8755ead8650bb589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Mussolini is from which country?', '{"A":"Italy","B":"France","C":"Russia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Benito Mussolini was an Italian politician and leader of the National Fascist Party.He ruled Italy as Prime Minister from 1922 until his ousting in 1943.He is known for his authoritarian and fascist regime, which allied with Nazi Germany and Japan during World War II.Mussolini was born in Predappio, Italy in 1883.He was executed in Milan, Italy in 1945.', 0, 0, 0, 1790965679018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7383e5a88bce7579', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Iron Dome is a Mobile Defence system developed by which country?', '{"A":"Israel","B":"Iran","C":"Japan","D":"USA"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iron Dome is an air defense system developed by Rafael Advanced Defense Systems and Israel Aerospace Industries.First, put into service in 2011, it is designed to stop short-range rockets and artillery like those fired from Gaza. In the ongoing conflict between Israel and Palestine, both sides launch air strikes and rocket attacks. Israel used the Iron Dome defense system for Defence.', 0, 0, 0, 1790965679018) ON CONFLICT(id) DO NOTHING;
