INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_11245eda9b8ec0a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country banned on telecommunication on China Huawei from its 5G network?', '{"A":"Japan","B":"India","C":"France","D":"UK"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The UK banned Huawei from its 5G network in 2020, citing security concerns.The decision required the removal of all Huawei equipment from UK 5G networks by 2027.', 0, 0, 0, 1790965679309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_adc278bb2181dc11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Acropolis of Athens situated in which country?', '{"A":"Greece","B":"India","C":"UK","D":"USA"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Acropolis of Athens is an ancient citadel located in the heart of Athens, Greece.It''s a UNESCO World Heritage Site and one of the most famous and iconic landmarks in Greece.The Acropolis is home to the Parthenon, a stunning ancient temple dedicated to the goddess Athena, as well as other ancient ruins and artifacts.', 0, 0, 0, 1790965679309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f2478e0c809d9bd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Horseshoe bay is situated in which country?', '{"A":"Australia","B":"Canada","C":"Japan","D":"Mexico"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Horseshoe Bay is a small coastal community located on the southern tip of Vancouver Island, British Columbia, Canada.It is situated about 30 kilometers (19 miles) west of Victoria, the capital city of British Columbia.', 0, 0, 0, 1790965679309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_57f1ecb5f17b884a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Iron cross was highest Military award of which country?', '{"A":"Germany","B":"Uk","C":"China","D":"Turkey"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Iron Cross (Eisernes Kreuz) was a military decoration established by King Frederick William III of Prussia in 1813.It was the highest military award of Germany until the end of World War I in 1918.It was revived as a military award by the Nazi regime in 1939.It was used until the end of World War II in 1945.', 0, 0, 0, 1790965679381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_907c5e47ca805b60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'In which country Great Buddha of Kamakura located?', '{"A":"Israel","B":"Japan","C":"Uk","D":"USA"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Buddha of Kamakura, also known as the Daibutsu.It is a large bronze statue of Amitābha Buddha located in Kotokuin Temple in Kamakura, Japan.It is one of the most famous and iconic landmarks in Japan.It has a popular tourist destination.', 0, 0, 0, 1790965679381) ON CONFLICT(id) DO NOTHING;
