INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_065b838b60e0fb76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Blind Dolphins are found in the river of:', '{"A":"Ganges River","B":"Nile River","C":"Yellow River","D":"Yangtze River","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blind Dolphins are found in Indus river in Pakistan and Ganges river in India and Bangladesh.***********The Indus River dolphin, also known as the “bhulan,” is one of the world''s most endangered cetaceans. It is endemic to the Indus River Basin of Pakistan and northwestern India. Blind Dolphins are found in the lower parts of the Indus River in Pakistan and in River Beas, a tributary of the Indus River in Punjab, India.ND20-6-2023', 0, 0, 0, 1790965680004) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c73572bb06897661', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Saba is the news agency of which country?', '{"A":"Iraq","B":"Indonesia","C":"Syria","D":"Yemen","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation News Agencies of Important CountriesPakistan: Associated Press of Pakistan (APP)China: XinhuaRussia: TASS (Telegrafnoye agentstvo Sovetskogo Soyuza) India: Press Trust of India (PTI)France: AFP (Agence France-Presse) (also oldest news agency)Italy: ANSA (Agenzia Nazionale Stampa Associata)USA: Associated Press (AP)Britain: Reuters Malaysia: Bernama Israel: ITIMBahrain: BNA (Bahrain News Agency)Iran: FARSSyria: SANA(Syrian Arab News Agency)Yemen: SABAIndonesia: Antara Kuwait: KUNA (Kuwait News Agency)Kenya: KNA (Kenya News Agency)', 0, 0, 0, 1790965680081) ON CONFLICT(id) DO NOTHING;
