INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4beefd9a1e3a5906', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Panga ya Saidi caves are located in which country?', '{"A":"Cuba","B":"Kenya","C":"Mexico","D":"Ukraine","E":"Poland"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scientists have discovered the oldest known human burial in Africa, at a location named “Panga ya Saidi”. It is an archaeological cave site located in South-Eastern Kenya. It is a burial of a child aged 2-1/2 or 3 years old, buried in a shallow grave with its head resting on a pillow. The burial is said to be more than 78,000 old.', 0, 0, 0, 1790965680157) ON CONFLICT(id) DO NOTHING;
