INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_06fd5e8a178a2145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who is the known as father/founder of Local Self-Government in India?', '{"A":"G G Lord Ripon","B":"Salmond","C":"Aristotle","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1882, Lord Ripon, the Viceroy and Governor-General of India, passed a resolution that established local self-government in India. This resolution is known as the Magna Carta of Local Self Government.Lord Ripon is also known as the "Good Viceroy of India".Other reforms by Lord Ripon include the Hunter Commission, the First Factory Act of 1881, and the reorganization of the Madras Forest Department.', 0, 0, 0, 1790965686921) ON CONFLICT(id) DO NOTHING;
