INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9528dae79dc718b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The First satellite in the World was?', '{"A":"Sputnik 1","B":"Sputnik 2","C":"Sputnik 3","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first artificial satellite in the world was Sputnik 1Launch Date: October 4, 1957Country: Soviet Union (USSR)Size: 58 centimeters (22.8 inches) in diameterWeight: 83.6 kilograms (183.9 pounds)Mission Life: Transmitted radio beeps for 3 weeks before batteries died; burned up in the atmosphere on January 4, 1958.Last updated 07-09-2026 by NA', 0, 0, 0, 1790965688486) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e258a4529bb605de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The most popular (populous) city in the world is?', '{"A":"Beijing","B":"Jakarta","C":"Shanghai","D":"Tokyo"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jakarta, Indonesia is the world''s most populous metropolitan city.Additional information:Jakarta, Indonesia: ~42 millionDhaka, Bangladesh: ~37 millionTokyo, Japan: ~33 millionNew Delhi, India: ~30 millionShanghai, China: ~29 millionLast verified on 02-06-2026', 0, 0, 0, 1790965688486) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b2e6fab87f350aeb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'What is the name of the fastest animal in the world?', '{"A":"Bear","B":"Lion","C":"Rabbit","D":"Cheetah"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Cheetah (Acinonyx jubatus)Top speed: ~109–120 km/hAcceleration: Can go 0 to 100 km/h in just a few secondsHabitat: Africa & parts of IranType: Carnivorous mammalAdditional information:The three-toed sloth is widely recognized as the slowest mammal on Earth.Last verified on 23-06-2026', 0, 0, 0, 1790965688486) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3ff0d0bfcd1ecbb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The largest bird in the world is?', '{"A":"Cranes Bald-eagle","B":"Ostrich","C":"Penguin","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The common ostrich (Struthio camelus) is the biggest bird in the world.It is weighing up to 344 pounds (157 kilograms) and standing 9 feet tall.Female ostriches lay the largest eggs of any living bird.Additional information:The world’s fastest bird is the peregrine falcon.The white bellbird is the world’s loudest bird.Last verified on 01-07-2026', 0, 0, 0, 1790965688486) ON CONFLICT(id) DO NOTHING;
