INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c71497d57467898e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Belt and Road Initiative (BRI) is a Chinese grand strategy was first launched in 2013 during the speech of Chinese President _____?', '{"A":"Xi Jin Ping","B":"Hu Jin Tao","C":"Jiang Zemin","D":"Wen Jia Bao"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Launched: 7th September 2013Founder / Initiator: Xi JinpingMain Goal: Global connectivity through roads, railways, ports, and energy projectsRegions Connected: Asia, Europe, Africa, and beyondParticipating Countries: Over 150 countriesLast verified on 10-03-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9d323ca82fd95dd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The World’s fastest bird is?', '{"A":"Humming Bird","B":"Ostrich","C":"Hen","D":"Peregrine falcon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peregrine Falcon is the world’s fastest bird.It can reach speeds of over 300 km/h (186 mph) during a hunting dive called a stoop.Its scientific name is Falco peregrinus.It is known for its exceptional speed and hunting ability.Additional information:Ostrich → Largest and Fastest running bird (up to 70 km/h / 43 mph)Last verified on 01-07-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b9cf4d750015b593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which is the largest exporter of Arms in the world?', '{"A":"USA","B":"Iran","C":"Iraq","D":"Saudi Arabia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Arms Exporter: USASecond Largest: RussiaThird Largest: FranceMain Buyers: Middle East, Europe, AsiaMain Products: Fighter jets, missiles, defense systems, military technologyLast verified on 16-06-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_832a0b3fb0d2a07f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which Muslim scientist wrote the first book on Algebra and is known as the Father of Algebra?', '{"A":"Ibn Sina","B":"Ibn Khaldun","C":"Al-Khwarizmi","D":"Euclid"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Khwarizmi is known as the Father of Algebra for writing the first systematic book on algebra.He wrote Al-Kitab al-Mukhtasar fi Hisab al-Jabr wal-Muqabala in the 9th century.The word “Algebra” comes from “Al-Jabr” in his book title.Last verified on 24-06-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_40ddb599c5efb302', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The Oldest University in the World is?', '{"A":"Cambridge University","B":"Oxford University","C":"University of Bologna","D":"University of Warwick"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The University of Bologna is the oldest university in the world.It is located in Bologna Italy.It is a public research university in Bologna.It was founded in 1088.It was founded by Irnerius.Additional information:The oldest University in Pakistan is King Edward Medical University.The oldest university in the USA is Harvard University.Last verified on 20-06-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ce71ae7282f147a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The first Gulf War started in?', '{"A":"1989","B":"1988","C":"1990","D":"1991"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The First Gulf War started in 1990 when Iraq invaded Kuwait.It began on 2 August 1990 with Iraq’s military action.The war ended in 1991 after a US-led coalition operation.It is also known as the Gulf War / Operation Desert Storm.It was caused by political and oil-related disputes between Iraq and Kuwait.Last verified on 11-06-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_79cc0cf0e967c0fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The biggest/largest State of the USA with regard to area is?', '{"A":"Alaska","B":"New York","C":"California","D":"Texas"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alaska is the largest state of the USA by area.It was purchased from Russia in 1867.Additional information:The United States of America is located in the North American continent.It consists of 50 states.California is the largest state of the USA by population.Texas is the 2nd largest state by area.Last verified on 27-04-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b9a36f1a1c6d1e34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The deepest part of the Earth is _____?', '{"A":"Dead sea","B":"Mariana Trench","C":"South Pole","D":"South Africa"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mariana Trench is the deepest part of the Earth.It is located in the western Pacific Ocean.Its deepest point is called Challenger Deep.Additional information:Depth: 10,994 metersLength: ~2,550 kmWidth: ~69 kmLast verified on 31-03-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4c2b8fa64e46bfc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The first Noble Prize was awarded in the year?', '{"A":"1900","B":"1901","C":"1902","D":"1903"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nobel Prize was first awarded in 1901Inaugurated on December 10, 1901Awarded in Stockholm, Sweden.Inventor of dynamite, Alfred NobelAdditional informationSince 1901, the Nobel Prize has been awarded in the fields ofPhysicsChemistry Physiology/Medicine Literature Peace Economics.Last updated question by NA on 07 May 2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e0676758f263ed1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The first person to draw the map of earth?', '{"A":"Heraclitus","B":"Phythagoras","C":"Anaximander","D":"Thales"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anaximander is credited with drawing one of the first known world maps.He lived in 6th century BC (around 610–546 BC).His map represented the known world as a flat circular surface.It was an early attempt to show geographical layout of Earth.Last verified on 02-05-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_421d575435ecacaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The lowest point on Earth is _____?', '{"A":"Dead Sea","B":"Indian Ocean","C":"River Nile","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dead Sea is the lowest point on Earth’s land surface.It lies in the Jordan Rift Valley between Jordan and Israel.Its surface is about 430 meters below sea level.It is a very salty lake, not a sea.The main inflow river is the Jordan River.Last verified on 02-05-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a32ffae4535e8801', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'When did India conduct its first nuclear test?', '{"A":"1974","B":"1970","C":"1978","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India conducted its first nuclear test on May 18, 1974Codename: Smiling Buddha (or Pokhran-I).Location: Pokhran, Rajasthan, India.Type: Plutonium fission device.Smiling Buddha, other name Pokhran-I Number of tests 1Last updated by NA on 24-April-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0599e1b586837a6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The Shortest day in Australia is _____?', '{"A":"22 December","B":"22 June","C":"21 June","D":"21 December"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Australia shortest day: 21 JuneAsia shortest day: 21 DecemberAustralia longest day: 21 DecemberAsia longest day: 21 JuneCaused by Earth’s axial tilt of 23.5°Last verified on 04-04-2026', 0, 0, 0, 1790965688693) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_79ae6bf816b2c135', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Neil Armstrong became the first human to step on the moon on _____?', '{"A":"July 20, 1972","B":"July 20, 1991","C":"July 20, 1969","D":"July 20, 1966"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neil Armstrong was the first human to set foot on the Moon on July 20, 1969, during NASA''s Apollo 11 mission.His famous words upon landing were, "That''s one small step for man, one giant leap for mankind."Neil Alden Armstrong was died on August 25, 2012.He was born on August 5, 1930.Last verified on 01-04-2026', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47e01993160023d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which is the world''s oldest monarchy?', '{"A":"Kuwait","B":"Japan","C":"Russia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Japan''s monarchy is the oldest surviving monarchy in the world.It was founded in 660 BCE, by Emperor Jimmu. The official records of royal succession date back to Emperor Ōjin''s reign in the 4th century.However, they have recognized 125 monarchs till now.Last verified on 30-03-2026', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4c481379f9a39a0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which day is considered as longest day in Northern Hemisphere?', '{"A":"7 June","B":"2 June","C":"21 June","D":"30 June"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 22 December night is the longest night of the year.21 June day the longest day of the year.Last verified on 19-03-2026', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ace9c017a14ddcf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The first political thinker to present the theory of sovereignty and absolute royal power to suppress the Anarchy was?', '{"A":"Harold Laski","B":"Johan Locke","C":"Thomas Hobbes","D":"Jean Bodln"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The French political philosopher Jean Bodin was the first to present the modern theory of sovereignty systematicallyLater philosophers like Thomas Hobbes expanded on this absolute theory in his work LeviathanLast verified on 23-02-2026', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a81ef8f4ca4b0e69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which is the highest battlefield in the world?', '{"A":"The Siachen Glacier","B":"Tibet","C":"Jafana","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest battlefield in the world is the Siachen GlacierA military dispute between India and Pakistan began on April 13, 1984.It has an average altitude of about 6,000 meters (20,000 feet).It is also known as the Siachen Glacier conflict.It is located in the Karakoram range in Kashmir.', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
