INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5bbe65f7577f9551', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which US president visited Pakistan first?', '{"A":"Dwight D Eisenhower","B":"George W. Bush","C":"Richard Nixon","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five Presidents of USA have visited Pakistan. They are following:NameLocaleRemarksDateDwight D. EisenhowerKarachiInformal visit; met with President Ayub Khan.December 7–9, 1959Lyndon B. JohnsonKarachiMet with President Ayub Khan.December 23, 1967Richard M. NixonLahoreState visit; met with President Yahya Khan.August 1–2, 1969William J. ClintonIslamabadMet with President Tarar and General Musharraf; delivered radio address.March 25, 2000George W. BushIslamabadMet with President Musharraf.March 3–4, 2006', 0, 0, 0, 1790965689307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7974a320819af1b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which is the highest railway bridge in the world?', '{"A":"Arrah–Chhapra Bridge","B":"Chenab Bridge","C":"Vijayghat Bridge","D":"Old Saraighat Bridge"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chenab Bridge is a rail bridge, located between Bakkal and Kauri in the Reasi district of Jammu and Kashmir (J&K), India. The 1,315m-long bridge is being built at a height of 359m.It is the tallest rail bridge in the world.', 0, 0, 0, 1790965689307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c52041b19904cb23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'During which year the first World War was started?', '{"A":"1912","B":"1913","C":"1914","D":"1915"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World War I lasted from 28 July 1914 to 11 November 1918.It was a global war originating in Europe.Chlorine gas was first used during World War I at Ypres in April 1915.After World War I, the influenza pandemic occurred in 1918.During World War I, Russia signed the Peace Treaty with Germany in 1917.World War II started in 1939 and ended in 1945.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d03b9eb303742012', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which of the following is considered the largest archipelago of the world?', '{"A":"Indonesia","B":"Philippines","C":"Virgin Islands","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indonesia is considered the largest archipelago in the world, comprising more than 17,000 islands.Including Sumatra, Java, Bali, and Kalimantan.It stretching from the northern tip of Sumatra to the southern edge of Papua.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bd524e3039857e3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The largest undersea railway tunnel is constructed between _____?', '{"A":"USA & Canada","B":"England & USA","C":"Japan & South Korea","D":"France & England"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest undersea railway tunnel is constructed between France & England***The largest undersea railway tunnel constructed between France & England is the Channel Tunnel This tunnel was built in 1988.The length of this tunnel is 31.4 Miles.***The project to build the undersea leg between England and France began in earnest in 1986. But as work progressed, the owner, Eurotunnel, and the Anglo-French consortium responsible for the design and construction', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4c8e773e21aa7990', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Baba Fareed Shaker Ganj'' was the first poet of:', '{"A":"Pushto","B":"Balochi","C":"Sindhi","D":"Punjabi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baba Farīd or Fariduddin Masud was born in 1188 (573 AH) in Kothewal He was a Sunni Muslim and was one of the founding fathers of the Chishti Sufi order.The Shrine of Baba Farid is a 13th-century Sufi shrine located in Pakpattan, PakistanBaba Fareed Shaker Ganj'' was the first poet of: PunjabiND17-1-2023', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_17cf03f1c1e3af0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The largest exporter of LNG is _____?', '{"A":"Qarar","B":"UAE","C":"Turkey","D":"USA"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The world''s largest exporter of liquefied natural gas (LNG) in 2022 was the United States, with an export volume of 114.4 billion cubic meters. At that time, Qatar ranked second.LNG is natural gas that been made into a liquid by cooling to -260 degrees Fahrenheit/-162 degrees Celsius for shipping and storage purposes.China imports more liquefied natural gas (LNG) than any other country in the world. In 2023, China purchased some 97.8 billion cubic meters worth of LNG.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f0dab35a5227d2cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The largest Helicopter in the world is _____?', '{"A":"Mil Mi-26","B":"CH-47 Chinook","C":"Hughes YOH-6A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest helicopter in the world is the Russian Air Force Mil Mi-26.Maximum Takeoff Weight: ~56,000 kg (123,500 lbs)Maximum Payload Capacity: ~20,000 kg (44,000 lbs)In terms of rotor length, the smallest helicopter is the GEN H-4, made by Gen Corporation (Japan).Rotor Length: 4 m (13 ft).Weight: 70 kg (154.32 lbs).Features: One seat, one landing gear, and one power unit.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4055ca4b0c588d0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The longest border of the United States is with ________?', '{"A":"Canada","B":"Mexico","C":"Denmark","D":"Brazil"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The international land border between the United States and Canada is the longest in the world.It stretching nearly 8,900 kilometers.It established on September 3, 1783, at the end of the American War of Independence.It spans 8,891 km (5,525 mi) in total.The border has two sections: one between Canada and the contiguous United States to the south, and another with the U.S. state of Alaska to the west.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d9beacfcfe592aa2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Longest military rule in the World is _____?', '{"A":"UK","B":"Japan","C":"Burma","D":"USA"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The longest military rule in the world was in Myanmar (Burma).It was lasting nearly 50 years, from 1962 to 2011.This period was marked by authoritarian governance and suppression of democratic movements.', 0, 0, 0, 1790965689419) ON CONFLICT(id) DO NOTHING;
