INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_98bb54bc43286308', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Largest Boeing plane in operation?', '{"A":"787Dreamliner","B":"788 dreamliner","C":"789 Dreamliner","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 747-8 is the world''s longest currently-operational passenger airliner, surpassing the Airbus A340-600 by 3.1 ft (0.95 m). With a maximum take-off weight of 975,000 lb (442 t), the 747-8 is the heaviest aircraft, commercial or military, manufactured in the U.S.', 0, 0, 0, 1790965690053) ON CONFLICT(id) DO NOTHING;
