INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_02a6a31118736ad5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The most famous book of 2008 “The Way of the World-A story of truth and hope in an age of extremism” is written by:', '{"A":"William Congreve","B":"H V Hudson","C":"Ron Suskind","D":"Ayesha Jalal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book “The Way of the World: A Story of Truth and Hope in an Age of Extremism” was written by Ron Suskind.It was published in 2008.Ron Suskind is an American journalist and author.The book focuses on global politics, extremism, and US foreign policy.', 0, 0, 0, 1790965690053) ON CONFLICT(id) DO NOTHING;
