INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cc1fa01a3a716a8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Abu Bakr al-Baghdadi is the self-styled leader of:', '{"A":"Shabab-e-Milli","B":"Hizbullah","C":"DAESH","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Bakr al-Baghdadi was the leader of the Islamic State of Iraq and Syria (ISIS), also known as DAESH.He was appointed the emir, or highest leader, of the Islamic State of Iraq on 16 May 2010.After the death of his predecessor Abu Omar al-Baghdadi.He was the Iraqi division of al-Qaeda.', 0, 0, 0, 1790965691595) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_27b419603b7e9ede', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Gerald R. Ford became US president by:', '{"A":"Appointment","B":"Elections","C":"Nomination","D":"Succession"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BANS:he 1976 United States presidential election was the 48th quadrennial presidential race. It was held on Tuesday, November 2, 1976. Democrat Jimmy Carter of Georgia vanquished occupant Republican President Gerald Portage from Michigan by a limit triumph of 297 constituent college votes to Ford''s 240.', 0, 0, 0, 1790965691595) ON CONFLICT(id) DO NOTHING;
