INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_07d342e1d205a658', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'The former US vice president Al gore has won Nobel Peace Prize 2007 for his campaign against', '{"A":"Global warming","B":"Child labor","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On October 12, 2007, former U.S. Vice President Al Gore and the United Nation''s Intergovernmental Panel on Climate Change are awarded the Nobel Peace PrizeAl Gore is the co-winner, of the Intergovernmental Panel on Climate Change, of the 2007 Nobel Peace Prize for “informing the world of the dangers posed by climate change.”', 0, 0, 0, 1790965691595) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e544a6a38ad415c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'The parliament of Turkey is:', '{"A":"Grand National Assembly","B":"Congress","C":"National Council","D":"Lok Sabha","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Grand National Assembly of Turkey is the unicameral Turkish legislature. It is the sole body given the legislative prerogatives by the Turkish Constitution. It was founded in Ankara on 23 April 1920.', 0, 0, 0, 1790965691595) ON CONFLICT(id) DO NOTHING;
