INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1cca4400ba37a296', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_days', 'Bastille Day is celebrated on _____?', '{"A":"July 11","B":"July 12","C":"July 13","D":"July 14"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bastille Day is the common name given in English-speaking countries to the national day of FranceBastille Day is celebrated on 14 July each year.In French, it is formally called the Fête nationale française; legally it is known as le 14 juilletCelebrations: Military parades, fireworks, concerts, balls', 0, 0, 0, 1790965694093) ON CONFLICT(id) DO NOTHING;
